pub(crate) fn hashEqSystem(mut eq: &metamodelica::Ref<SimCode::SimEqSystem>) -> Result<i32> {
    let mut hash: i32;
    hash = (::match_deref::match_deref! { match eq {
        Deref @ SimCode::SimEqSystem::SES_RESIDUAL { exp: __eq_exp, .. } => {
            ExpressionBasics::hashExp(metamodelica::AsArg::as_arg(&__eq_exp))?
        },
        Deref @ SimCode::SimEqSystem::SES_FOR_RESIDUAL { exp: __eq_exp, .. } => {
            ExpressionBasics::hashExp(metamodelica::AsArg::as_arg(&__eq_exp))?
        },
        Deref @ SimCode::SimEqSystem::SES_GENERIC_RESIDUAL { exp: __eq_exp, .. } => {
            ExpressionBasics::hashExp(metamodelica::AsArg::as_arg(&__eq_exp))?
        },
        Deref @ SimCode::SimEqSystem::SES_SIMPLE_ASSIGN { cref: __eq_cref, exp: __eq_exp, .. } => {
            ComponentReferenceBasics::hashComponentRef(metamodelica::AsArg::as_arg(&__eq_cref))? + 7 * ExpressionBasics::hashExp(metamodelica::AsArg::as_arg(&__eq_exp))?
        },
        Deref @ SimCode::SimEqSystem::SES_SIMPLE_ASSIGN_CONSTRAINTS { cref: __eq_cref, exp: __eq_exp, .. } => {
            ComponentReferenceBasics::hashComponentRef(metamodelica::AsArg::as_arg(&__eq_cref))? + 7 * ExpressionBasics::hashExp(metamodelica::AsArg::as_arg(&__eq_exp))?
        },
        Deref @ SimCode::SimEqSystem::SES_ARRAY_CALL_ASSIGN { exp: __eq_exp, lhs: __eq_lhs, .. } => {
            ExpressionBasics::hashExp(metamodelica::AsArg::as_arg(&__eq_lhs))? + 7 * ExpressionBasics::hashExp(metamodelica::AsArg::as_arg(&__eq_exp))?
        },
        Deref @ SimCode::SimEqSystem::SES_ALGORITHM { statements: Deref @ metamodelica::ListNode::Cons { head: stmt @ Deref @ DAE::Statement::STMT_ASSERT { .. }, tail: Deref @ metamodelica::ListNode::Nil }, .. } => {
            ExpressionBasics::hashExp(var_field!((**stmt).cond, DAE::Statement::STMT_ASSERT))? + 7 * ExpressionBasics::hashExp(var_field!((**stmt).msg, DAE::Statement::STMT_ASSERT))? + 49 * ExpressionBasics::hashExp(var_field!((**stmt).level, DAE::Statement::STMT_ASSERT))?
        },
        _ => {
            metamodelica::valueConstructor((&*&**eq))?
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(hash)
}

