fn createEquationsForSystems1(
    mut inSyst: metamodelica::Ref<BackendDAE::EqSystem>,
    mut zcVars: &metamodelica::Ref<AvlSetInt::Tree>,
    mut inArg: &CreateEquationsForSystemsArg,
    mut inFold: CreateEquationsForSystemsFold,
) -> Result<CreateEquationsForSystemsFold> {
    let mut outFold: CreateEquationsForSystemsFold;
    outFold = (match &*inSyst.matching.clone() {
        BackendDAE::Matching::MATCHING { ass1, comps, .. } => {
            let mut odeEquations1: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
            let mut algebraicEquations1: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
            let mut allEquations1: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
            let mut syst: metamodelica::Ref<BackendDAE::EqSystem>;
            let mut odeEquations: metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>;
            let mut algebraicEquations: metamodelica::List<
                metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>,
            >;
            let mut allEquations: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
            let mut equationsForZeroCrossings: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
            let mut equationsForZeroCrossings1: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
            let mut uniqueEqIndex: i32;
            let mut sccOffset: i32;
            let mut stateeqnsmark: metamodelica::Array<i32>;
            let mut zceqnsmarks: metamodelica::Array<i32>;
            let mut tempvars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>;
            let mut funcs: metamodelica::Ref<AvlTreePathFunction::Tree>;
            let mut eqSccMapping: metamodelica::List<(i32, i32)>;
            let mut eqBackendSimCodeMapping: metamodelica::List<(i32, i32)>;
            let mut backendMapping: SimCode::BackendMapping;
            let mut shared: metamodelica::Ref<BackendDAE::Shared>;
            let mut createAlgebraicEquations: bool;
            if Flags::isSet(Flags::BLT_MATRIX_DUMP.clone())? {
                BackendDump::dumpEqSystemBLTmatrixHTML(&inSyst)?;
            }
            (shared, createAlgebraicEquations) = inArg.clone();
            (
                uniqueEqIndex,
                odeEquations,
                algebraicEquations,
                allEquations,
                equationsForZeroCrossings,
                tempvars,
                eqSccMapping,
                eqBackendSimCodeMapping,
                backendMapping,
                sccOffset,
            ) = inFold;
            funcs = BackendDAEUtil::getFunctions(&shared);
            (syst, _, _) = BackendDAEUtil::getAdjacencyMatrixfromOption(
                inSyst,
                openmodelica_backend_types::BackendDAE::IndexType::ABSOLUTE,
                Some(funcs),
                BackendDAEUtil::isInitializationDAE(&shared),
            )?;
            stateeqnsmark = arrayCreate(BackendDAEUtil::equationArraySizeDAE(&syst), 0);
            zceqnsmarks = arrayCreate(BackendDAEUtil::equationArraySizeDAE(&syst), 0);
            stateeqnsmark = BackendDAEUtil::markStateEquations(&syst, stateeqnsmark.clone(), ass1.clone())?;
            zceqnsmarks = BackendDAEUtil::markZeroCrossingEquations(&syst, zcVars, zceqnsmarks.clone(), ass1.clone())?;
            (
                odeEquations1,
                algebraicEquations1,
                allEquations1,
                equationsForZeroCrossings1,
                uniqueEqIndex,
                tempvars,
                eqSccMapping,
                eqBackendSimCodeMapping,
                backendMapping,
            ) = createEquationsForSystem(
                stateeqnsmark.clone(),
                zceqnsmarks.clone(),
                syst,
                shared,
                metamodelica::AsArg::as_arg(&comps),
                uniqueEqIndex,
                tempvars,
                sccOffset,
                eqSccMapping,
                eqBackendSimCodeMapping,
                backendMapping,
                createAlgebraicEquations,
            )?;
            GCExt::free(stateeqnsmark.clone());
            GCExt::free(zceqnsmarks.clone());
            odeEquations = List::consOnTrue(!((odeEquations1).is_empty()), odeEquations1, odeEquations);
            algebraicEquations = List::consOnTrue(
                !((algebraicEquations1).is_empty()),
                algebraicEquations1,
                algebraicEquations,
            );
            allEquations = List::append_reverse(&allEquations1, allEquations);
            equationsForZeroCrossings = List::append_reverse(&equationsForZeroCrossings1, equationsForZeroCrossings);
            (
                uniqueEqIndex,
                odeEquations,
                algebraicEquations,
                allEquations,
                equationsForZeroCrossings,
                tempvars,
                eqSccMapping,
                eqBackendSimCodeMapping,
                backendMapping,
                ((comps).len() as i32) + sccOffset,
            )
        }
        _ => inFold,
    });
    Ok(outFold)
}

