fn replaceIFBrancheswithoutVar(
    mut inExp: metamodelica::Ref<DAE::Exp>,
    mut inTpl: (metamodelica::Ref<DAE::Exp>, metamodelica::Ref<DAE::Exp>),
) -> Result<(
    metamodelica::Ref<DAE::Exp>,
    (metamodelica::Ref<DAE::Exp>, metamodelica::Ref<DAE::Exp>),
)> {
    let mut outExp: metamodelica::Ref<DAE::Exp>;
    let mut outTpl: (metamodelica::Ref<DAE::Exp>, metamodelica::Ref<DAE::Exp>);
    (outExp, outTpl) = (::match_deref::match_deref! { match &((inExp.clone(), inTpl.clone())) {
        (Deref @ DAE::Exp::IFEXP { expCond: cond, expThen: e1, expElse: e2 }, (crexp, exp)) => {
            let mut b1: bool;
            let mut b2: bool;
            let mut e1 = (*e1).clone();
            let mut e2 = (*e2).clone();
            b1 = Expression::expContains(metamodelica::AsArg::as_arg(&e1), metamodelica::AsArg::as_arg(&crexp))?;
            e1 = if (b1) {e1.clone()} else {exp.clone()};
            b2 = Expression::expContains(metamodelica::AsArg::as_arg(&e2), metamodelica::AsArg::as_arg(&crexp))?;
            e2 = if (b2) {e2.clone()} else {exp.clone()};
            (if (b1 && b2) {inExp} else {metamodelica::Ref::new(DAE::Exp::IFEXP { expCond: cond.clone(), expThen: e1.clone(), expElse: e2.clone() })}, inTpl)
        },
        _ => {
            (inExp, inTpl)
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok((outExp, outTpl))
}

fn solveAlgorithmInverse(
    mut inStmts: &metamodelica::List<metamodelica::Ref<DAE::Statement>>,
    mut inSolveFor: &metamodelica::List<metamodelica::Ref<BackendDAE::Var>>,
) -> Result<metamodelica::List<metamodelica::Ref<DAE::Statement>>> {
    let mut outStmts: metamodelica::List<metamodelica::Ref<DAE::Statement>>;
    outStmts = (::match_deref::match_deref! { match (inStmts, inSolveFor) {
        (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_ASSIGN { exp1: e11, exp: e12, source: source1, .. }, tail: Deref @ metamodelica::ListNode::Nil }, Deref @ metamodelica::ListNode::Cons { head: v1 @ Deref @ BackendDAE::Var { varName: cr1, .. }, tail: Deref @ metamodelica::ListNode::Nil }) => {
            let mut varexp1: metamodelica::Ref<DAE::Exp>;
            let mut solvedExp1: metamodelica::Ref<DAE::Exp>;
            let mut tp1: metamodelica::Ref<DAE::Type>;
            let mut asserts: metamodelica::List<metamodelica::Ref<DAE::Statement>>;
            let mut source1 = (*source1).clone();
            let mut cr1 = (*cr1).clone();
            varexp1 = Expression::crefExp(cr1.clone())?;
            varexp1 = if (BackendVariable::isStateVar(metamodelica::AsArg::as_arg(&v1))) {Expression::expDer(varexp1)} else {varexp1};
            (solvedExp1, asserts) = ExpressionSolve::solve(e11.clone(), e12.clone(), varexp1.clone(), None)?;
            cr1 = if (BackendVariable::isStateVar(metamodelica::AsArg::as_arg(&v1))) {ComponentReference::crefPrefixDer(cr1.clone())} else {cr1.clone()};
            source1 = ElementSource::addSymbolicTransformationSolve(true, source1.clone(), cr1.clone(), e11.clone(), e12.clone(), solvedExp1.clone(), asserts)?;
            tp1 = Expression::r#typeof(varexp1.clone())?;
            list![metamodelica::Ref::new(DAE::Statement::STMT_ASSIGN { type_: tp1, exp1: varexp1, exp: solvedExp1, source: source1.clone() })]
        },
        (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_ASSIGN { exp1: e11, exp: e12, source: source1, .. }, tail: Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_ASSIGN { exp1: e21, exp: e22, source: source2, .. }, tail: Deref @ metamodelica::ListNode::Nil } }, Deref @ metamodelica::ListNode::Cons { head: v1 @ Deref @ BackendDAE::Var { varName: cr1, .. }, tail: Deref @ metamodelica::ListNode::Cons { head: v2 @ Deref @ BackendDAE::Var { varName: cr2, .. }, tail: Deref @ metamodelica::ListNode::Nil } }) => {
            let mut varexp1: metamodelica::Ref<DAE::Exp>;
            let mut solvedExp1: metamodelica::Ref<DAE::Exp>;
            let mut tp1: metamodelica::Ref<DAE::Type>;
            let mut varexp2: metamodelica::Ref<DAE::Exp>;
            let mut solvedExp2: metamodelica::Ref<DAE::Exp>;
            let mut tp2: metamodelica::Ref<DAE::Type>;
            let mut asserts: metamodelica::List<metamodelica::Ref<DAE::Statement>>;
            let mut source1 = (*source1).clone();
            let mut source2 = (*source2).clone();
            let mut cr1 = (*cr1).clone();
            let mut cr2 = (*cr2).clone();
            let false = (Expression::expHasCref(e12.clone(), cr2.clone())?) else { return Err("pattern mismatch") };
            let false = (Expression::expHasCref(e22.clone(), cr1.clone())?) else { return Err("pattern mismatch") };
            varexp1 = Expression::crefExp(cr1.clone())?;
            varexp1 = if (BackendVariable::isStateVar(metamodelica::AsArg::as_arg(&v1))) {Expression::expDer(varexp1)} else {varexp1};
            (solvedExp1, asserts) = ExpressionSolve::solve(e11.clone(), e12.clone(), varexp1.clone(), None)?;
            cr1 = if (BackendVariable::isStateVar(metamodelica::AsArg::as_arg(&v1))) {ComponentReference::crefPrefixDer(cr1.clone())} else {cr1.clone()};
            source1 = ElementSource::addSymbolicTransformationSolve(true, source1.clone(), cr1.clone(), e11.clone(), e12.clone(), solvedExp1.clone(), asserts)?;
            tp1 = Expression::r#typeof(varexp1.clone())?;
            varexp2 = Expression::crefExp(cr2.clone())?;
            varexp2 = if (BackendVariable::isStateVar(metamodelica::AsArg::as_arg(&v2))) {Expression::expDer(varexp2)} else {varexp2};
            (solvedExp2, asserts) = ExpressionSolve::solve(e21.clone(), e22.clone(), varexp2.clone(), None)?;
            cr2 = if (BackendVariable::isStateVar(metamodelica::AsArg::as_arg(&v2))) {ComponentReference::crefPrefixDer(cr2.clone())} else {cr2.clone()};
            source2 = ElementSource::addSymbolicTransformationSolve(true, source2.clone(), cr2.clone(), e21.clone(), e22.clone(), solvedExp2.clone(), asserts)?;
            tp2 = Expression::r#typeof(varexp2.clone())?;
            list![metamodelica::Ref::new(DAE::Statement::STMT_ASSIGN { type_: tp1, exp1: varexp1, exp: solvedExp1, source: source1.clone() }), metamodelica::Ref::new(DAE::Statement::STMT_ASSIGN { type_: tp2, exp1: varexp2, exp: solvedExp2, source: source2.clone() })]
        },
        _ => return Err("match: no arm matched"),
    } });
    Ok(outStmts)
}

