pub(crate) fn fixNonlinearResidualIndices(
    mut inSysts: &metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>,
) -> metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>> {
    let mut outSysts: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>> = metamodelica::nil();
    let mut index: i32 = 0;
    for mut syst in &**inSysts {
        let mut syst = syst.clone();
        syst = (match &*syst {
            SimCode::SimEqSystem::SES_RESIDUAL { .. } => {
                assign_variant_field!(syst => SimCode::SimEqSystem::SES_RESIDUAL; res_index = index);
                index = index + 1;
                syst
            }
            _ => syst,
        });
        outSysts = metamodelica::cons(syst, outSysts);
    }
    outSysts = outSysts.reverse();
    outSysts
}

