                ident = ComponentReferenceBasics::printComponentRefStr(metamodelica::AsArg::as_arg(&cref))?;
                tp = Types::arrayElementType(&(ComponentReference::crefLastType(metamodelica::AsArg::as_arg(&cref))?));
