fn makeSES_RESIDUAL(
    mut inExp: metamodelica::Ref<DAE::Exp>,
    mut source: metamodelica::Ref<DAE::ElementSource>,
    mut eqAttr: BackendDAE::EquationAttributes,
    mut idx_tpl: (i32, i32),
) -> (metamodelica::Ref<SimCode::SimEqSystem>, (i32, i32)) {
    let mut outSimEqn: metamodelica::Ref<SimCode::SimEqSystem>;
    let mut idx_tpl: (i32, i32) = idx_tpl;
    let mut eq_idx: i32;
    let mut res_idx: i32;
    (eq_idx, res_idx) = idx_tpl;
    outSimEqn = metamodelica::Ref::new(SimCode::SimEqSystem::SES_RESIDUAL {
        index: eq_idx,
        res_index: res_idx,
        exp: inExp,
        source: source,
        eqAttr: eqAttr,
    });
    idx_tpl = (eq_idx + 1, res_idx + 1);
    (outSimEqn, idx_tpl)
}

