fn assignRecordElements(
    mut elems: metamodelica::List<metamodelica::Ref<DAE::Exp>>,
    mut varLst: metamodelica::List<metamodelica::Ref<DAE::Var>>,
    mut cref: &metamodelica::Ref<DAE::ComponentRef>,
    mut source: metamodelica::Ref<DAE::ElementSource>,
    mut eqAttr: BackendDAE::EquationAttributes,
    mut iuniqueEqIndex: i32,
) -> Result<(metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>, i32)> {
    let mut outSimEqn: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>> = metamodelica::nil();
    let mut ouniqueEqIndex: i32 = iuniqueEqIndex;
    let mut eqns: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
    let mut eqn: metamodelica::Ref<SimCode::SimEqSystem> =
        <metamodelica::Ref<SimCode::SimEqSystem> as ::std::default::Default>::default();
    for mut tpl in &*List::zip(
        elems,
        ({
            let mut __acc: metamodelica::List<metamodelica::Ref<DAE::Exp>> = metamodelica::nil();
            for mut v in (varLst).into_iter().cloned() {
                let __x = Expression::generateCrefsExpFromExpVar(&(v.clone()), cref)?;
                __acc = cons(__x, __acc);
            }
            __acc.reverse()
        }),
    ) {
        (eqns, ouniqueEqIndex) = makeSES_SIMPLE_ASSIGNwithArray(tpl.clone(), source.clone(), eqAttr, ouniqueEqIndex)?;
        for mut eqn in &*eqns {
            let mut eqn = eqn.clone();
            outSimEqn = metamodelica::cons(eqn, outSimEqn);
        }
    }
    outSimEqn = outSimEqn.reverse();
    Ok((outSimEqn, ouniqueEqIndex))
}

