fn generateInnerEqns(
    mut innerEquations: &metamodelica::List<BackendDAE::InnerEquation>,
    mut syst: &metamodelica::Ref<BackendDAE::EqSystem>,
    mut shared: &metamodelica::Ref<BackendDAE::Shared>,
    mut uniqueEqIndex: i32,
) -> Result<(
    metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>,
    metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
    i32,
)> {
    let mut equations: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>> = metamodelica::nil();
    let mut outputVars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>> = metamodelica::nil();
    let mut uniqueEqIndex: i32 = uniqueEqIndex;
    let mut eqnindx: i32;
    let mut vars: metamodelica::List<i32>;
    let mut tmpOutputVars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>;
    let mut tmpVars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
    let mut eqn: metamodelica::Ref<BackendDAE::Equation>;
    let mut comp: metamodelica::Ref<BackendDAE::StrongComponent>;
    let mut dblLstEqns: DoubleEnded::MutableList<metamodelica::Ref<SimCode::SimEqSystem>>;
    let mut omsiFuncEquations: metamodelica::Ref<SimCode::OMSIFunction>;
    dblLstEqns = DoubleEnded::fromList(&equations)?;
    for mut eq in &**innerEquations {
        (eqnindx, vars, _) = BackendDAEUtil::getEqnAndVarsFromInnerEquation(metamodelica::AsArg::as_arg(&eq));
        tmpVars = List::map1r(
            vars.clone(),
            &move |__a0: BackendDAE::Variables, __a1: i32| BackendVariable::getVarAt(&__a0, __a1),
            syst.orderedVars.clone(),
        )?;
        tmpVars = BackendVariable::setVarsKind(tmpVars, openmodelica_backend_types::BackendDAE::VarKind::LOOP_SOLVED)?;
        (tmpOutputVars, _) = List::fold(
            &tmpVars,
            &move |__a0: metamodelica::Ref<BackendDAE::Var>,
                   __a1: (
                metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
                BackendDAE::Variables,
            )| traversingdlowvarToSimvarFold(__a0, &__a1),
            (metamodelica::nil(), BackendVariable::emptyVars(0)),
        )?;
        outputVars = List::append_reverse(&tmpOutputVars, outputVars);
        eqn = BackendEquation::get(syst.orderedEqs.clone(), eqnindx)?;
        comp = createTornSystemInnerEqns1(eqn, eqnindx, vars)?;
        (omsiFuncEquations, uniqueEqIndex) =
            generateEquationsForComponents(&(list![comp]), syst, shared, uniqueEqIndex)?;
        DoubleEnded::push_list_back(dblLstEqns.clone(), &omsiFuncEquations.equations)?;
    }
    outputVars = Dangerous::listReverseInPlace(outputVars);
    equations = DoubleEnded::toListAndClear(dblLstEqns, metamodelica::nil())?;
    Ok((equations, outputVars, uniqueEqIndex))
}

fn appendOMSIFunction(
    mut omsiFunction_1: metamodelica::Ref<SimCode::OMSIFunction>,
    mut omsiFunction_2: &metamodelica::Ref<SimCode::OMSIFunction>,
) -> Result<metamodelica::Ref<SimCode::OMSIFunction>> {
    let mut omsiFunction_1: metamodelica::Ref<SimCode::OMSIFunction> = omsiFunction_1;
    assign_field!(
        omsiFunction_1.equations = listAppend(omsiFunction_1.equations.clone(), omsiFunction_2.equations.clone()),
        omsiFunction_1.inputVars = listAppend(omsiFunction_1.inputVars.clone(), omsiFunction_2.inputVars.clone()),
        omsiFunction_1.outputVars = listAppend(omsiFunction_1.outputVars.clone(), omsiFunction_2.outputVars.clone()),
        omsiFunction_1.innerVars = listAppend(omsiFunction_1.innerVars.clone(), omsiFunction_2.innerVars.clone()),
        omsiFunction_1.nAllVars = omsiFunction_1.nAllVars.clone() + omsiFunction_2.nAllVars.clone()
    );
    assign_field!(
        omsiFunction_1.context = (match omsiFunction_1.context.clone() {
            SimCodeFunction::Context::OMSI_CONTEXT {
                hashTable: Some(mut hashTable),
            } => {
                hashTable = List::fold(
                    &omsiFunction_2.inputVars,
                    &HashTableCrefSimVar::addSimVarToHashTable,
                    hashTable.clone(),
                )?;
                for mut simVar in &*omsiFunction_2.outputVars.clone() {
                    hashTable = HashTableCrefSimVar::addSimVarToHashTable(simVar.clone(), hashTable.clone())?;
                }
                for mut simVar in &*omsiFunction_2.innerVars.clone() {
                    hashTable = HashTableCrefSimVar::addSimVarToHashTable(simVar.clone(), hashTable.clone())?;
                }
                SimCodeFunction::Context::OMSI_CONTEXT {
                    hashTable: Some(hashTable.clone()),
                }
            }
            _ => return Err("match: no arm matched"),
        }),
        omsiFunction_1.nAlgebraicSystems =
            omsiFunction_1.nAlgebraicSystems.clone() + omsiFunction_2.nAlgebraicSystems.clone()
    );
    Ok(omsiFunction_1)
}

fn fillLocalHashTable(
    mut varListList: &metamodelica::List<metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>>,
    mut numberOfElements: i32,
) -> Result<(
    metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::ComponentRef>, i32)>>,
    (
        i32,
        i32,
        metamodelica::Array<
            Option<(
                metamodelica::Ref<DAE::ComponentRef>,
                metamodelica::Ref<SimCodeVar::SimVar>,
            )>,
        >,
    ),
    i32,
    (
        Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::ComponentRef>) -> Result<i32> + 'static>,
        Arc<
            dyn ::std::ops::Fn(
                    metamodelica::Ref<DAE::ComponentRef>,
                    metamodelica::Ref<DAE::ComponentRef>,
                ) -> Result<bool>
                + 'static,
        >,
        Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::ComponentRef>) -> Result<ArcStr> + 'static>,
        Arc<dyn ::std::ops::Fn(metamodelica::Ref<SimCodeVar::SimVar>) -> Result<ArcStr> + 'static>,
    ),
)> {
    let mut hashTable: (
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::ComponentRef>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<
                Option<(
                    metamodelica::Ref<DAE::ComponentRef>,
                    metamodelica::Ref<SimCodeVar::SimVar>,
                )>,
            >,
        ),
        i32,
        (
            HashTableCrefSimVar::FuncHashCref,
            HashTableCrefSimVar::FuncCrefEqual,
            HashTableCrefSimVar::FuncCrefStr,
            HashTableCrefSimVar::FuncExpStr,
        ),
    );
    let mut sizeHT: i32;
    sizeHT = std::cmp::max(1013, Util::nextPrime(numberOfElements * 2));
    hashTable = HashTableCrefSimVar::emptyHashTableSized(sizeHT);
    for mut simVarList in &**varListList {
        hashTable = List::fold(
            metamodelica::AsArg::as_arg(&simVarList),
            &HashTableCrefSimVar::addSimVarToHashTable,
            hashTable,
        )?;
    }
    Ok(hashTable)
}

