                    let mut simequations: metamodelica::List<SimCode::StateSet>;
                    let mut tempvars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>;
                    let mut simCodeAVars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>;
                    let mut uniqueEqIndex: i32;
