                    crstates = List::map(statevars.clone(), &move |__a0: metamodelica::Ref<BackendDAE::Var>| -> metamodelica::Result<_> { ::std::result::Result::Ok(BackendVariable::varCref(&__a0)) })?;
                    simCodeAVars = List::map3(aVars.clone(), &move |__a0: metamodelica::Ref<BackendDAE::Var>, __a1: Option<BackendDAE::Variables>, __a2: BackendDAE::Variables, __a3: Option<metamodelica::Ref<UnorderedSet::UnorderedSet<metamodelica::Ref<DAE::ComponentRef>>>>| dlowvarToSimvar(&__a0, __a1, __a2, __a3), None, iVars.clone(), None)?;
