                    uniqueEqIndex = metamodelica::Own::own(__pa1);
                    tempvars = metamodelica::Own::own(__pa2);
                    (simequations, uniqueEqIndex, tempvars, numStateSets) = createStateSetsSets(metamodelica::AsArg::as_arg(&sets), iVars, iEqns.clone(), comps, &(metamodelica::cons(SimCode::StateSet { index: iuniqueEqIndex, nCandidates: nCandidates, nStates: rang.clone(), states: crset.clone(), statescandidates: crstates.clone(), crA: crA.clone(), jacobianMatrix: jacobianMatrix.clone() }, iEquations.clone())), uniqueEqIndex, &tempvars, iNumStateSets + 1)?;
