pub fn syncDAEandSimJac(
    mut symJac: metamodelica::Ref<SimCode::JacobianMatrix>,
    mut daeJac: metamodelica::Ref<SimCode::JacobianMatrix>,
) -> Result<metamodelica::Ref<SimCode::JacobianMatrix>> {
    let mut daeJac: metamodelica::Ref<SimCode::JacobianMatrix> = daeJac;
    if metamodelica::stringEq(&symJac.matrixName, &(literal!("A"))) {
        assign_field!(
            daeJac.columns = ({
                let mut __acc: metamodelica::List<metamodelica::Ref<SimCode::JacobianColumn>> = metamodelica::nil();
                for mut col in (symJac.columns.clone()).into_iter().cloned() {
                    let __x = updateSimVarIndex(col.clone(), daeJac.crefsHT.clone())?;
                    __acc = cons(__x, __acc);
                }
                __acc.reverse()
            }),
            daeJac.jacobianIndex = symJac.jacobianIndex.clone()
        );
    } else {
        daeJac = symJac;
    }
    Ok(daeJac)
}

pub(crate) fn updateSimVarIndex(
    mut column: metamodelica::Ref<SimCode::JacobianColumn>,
    mut crefsHT: Option<(
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::ComponentRef>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<
                Option<(
                    metamodelica::Ref<DAE::ComponentRef>,
                    metamodelica::Ref<SimCodeVar::SimVar>,
                )>,
            >,
        ),
        i32,
        (
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::ComponentRef>) -> Result<i32> + 'static>,
            Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<DAE::ComponentRef>,
                        metamodelica::Ref<DAE::ComponentRef>,
                    ) -> Result<bool>
                    + 'static,
            >,
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::ComponentRef>) -> Result<ArcStr> + 'static>,
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<SimCodeVar::SimVar>) -> Result<ArcStr> + 'static>,
        ),
    )>,
) -> Result<metamodelica::Ref<SimCode::JacobianColumn>> {
    let mut column: metamodelica::Ref<SimCode::JacobianColumn> = column;
    column = (match crefsHT {
        Some(mut table) => {
            assign_field!(
                column.columnVars = ({
                    let mut __acc: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>> = metamodelica::nil();
                    for mut var in (column.columnVars.clone()).into_iter().cloned() {
                        let __x = BaseHashTable::getOrDefault(var.name.clone(), &table, var.clone())?;
                        __acc = cons(__x, __acc);
                    }
                    __acc.reverse()
                })
            );
            column
        }
        _ => column,
    });
    Ok(column)
}

fn getFurtherVars(
    mut v: metamodelica::Ref<BackendDAE::Var>,
    mut inTpl: (
        metamodelica::List<metamodelica::Ref<BackendDAE::Var>>,
        metamodelica::Ref<DAE::ComponentRef>,
    ),
) -> Result<(
    metamodelica::Ref<BackendDAE::Var>,
    (
        metamodelica::List<metamodelica::Ref<BackendDAE::Var>>,
        metamodelica::Ref<DAE::ComponentRef>,
    ),
)> {
    let mut outVar: metamodelica::Ref<BackendDAE::Var> = v.clone();
    let mut outTpl: (
        metamodelica::List<metamodelica::Ref<BackendDAE::Var>>,
        metamodelica::Ref<DAE::ComponentRef>,
    ) = inTpl.clone();
    let mut diffCref: metamodelica::Ref<DAE::ComponentRef>;
    let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
    let mut b: bool;
    (vars, diffCref) = inTpl;
    b = ComponentReferenceBasics::crefLastIdentEqual(&(BackendVariable::varCref(&v)), &diffCref)?;
    if !(b) {
        vars = metamodelica::cons(v, vars);
        outTpl = (vars, diffCref);
    }
    Ok((outVar, outTpl))
}

