        let mut allEquations: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>> = metamodelica::nil();
        let mut constantEqns: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>> = metamodelica::nil();
