                    let mut residualVars: BackendDAE::Variables;
                    let mut systvars: BackendDAE::Variables;
                    let mut allVars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
                    let mut x: metamodelica::Ref<DAE::ComponentRef>;
                    let mut coloring: metamodelica::List<metamodelica::List<i32>>;
                    let mut sparseInts: metamodelica::List<(i32, metamodelica::List<i32>)>;
                    let mut sparseIntsT: metamodelica::List<(i32, metamodelica::List<i32>)>;
                    let mut dummyVar: ArcStr;
