                    if Flags::isSet(Flags::JAC_DUMP2.clone())? {
                        metamodelica::print({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("analytical Jacobians -> created all SimCode equations for Matrix ")); __mm_s.push_str(&*name); __mm_s.push_str(&*literal!(" time: ")); __mm_s.push_str(&*realString(clock())); __mm_s.push_str(&*literal!("\n")); ArcStr::from(__mm_s) });
                    }
