                    x = metamodelica::Ref::new(DAE::ComponentRef::CREF_IDENT { ident: dummyVar.clone(), identType: DAE::T_REAL_DEFAULT().clone(), subscriptLst: metamodelica::nil() });
                    emptyVars = BackendVariable::emptyVars(BaseHashTable::bigBucketSize.clone());
