                    (allVars, _) = BackendVariable::traverseBackendDAEVars(syst.orderedVars.clone(), (std::sync::Arc::new(getFurtherVars) as std::sync::Arc<dyn ::std::ops::Fn(metamodelica::Ref<BackendDAE::Var>, (metamodelica::List<metamodelica::Ref<BackendDAE::Var>>, metamodelica::Ref<DAE::ComponentRef>)) -> Result<(metamodelica::Ref<BackendDAE::Var>, (metamodelica::List<metamodelica::Ref<BackendDAE::Var>>, metamodelica::Ref<DAE::ComponentRef>))> + 'static>), (metamodelica::nil(), x.clone()))?;
                    systvars = BackendVariable::listVar1(&allVars)?;
