                        metamodelica::print(Tpl::tplString((std::sync::Arc::new(move |__a0: Tpl::Text, __a1: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>| SimCodeDump::dumpVarsShort(__a0, &__a1)) as std::sync::Arc<dyn ::std::ops::Fn(Tpl::Text, metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>) -> Result<Tpl::Text> + 'static>), seedVars.clone())?);
                        metamodelica::print(literal!("\n---+++ indexVars variables +++---\n"));
                        metamodelica::print(Tpl::tplString((std::sync::Arc::new(move |__a0: Tpl::Text, __a1: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>| SimCodeDump::dumpVarsShort(__a0, &__a1)) as std::sync::Arc<dyn ::std::ops::Fn(Tpl::Text, metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>) -> Result<Tpl::Text> + 'static>), indexVars.clone())?);
