pub(crate) fn extractJacobianDelayedExpressions(
    mut delayedExps: metamodelica::List<(
        i32,
        (
            metamodelica::Ref<DAE::Exp>,
            metamodelica::Ref<DAE::Exp>,
            metamodelica::Ref<DAE::Exp>,
        ),
    )>,
    mut maxDelayedExpIndex: i32,
    mut SymJacs: metamodelica::List<metamodelica::Ref<SimCode::JacobianMatrix>>,
) -> Result<(
    metamodelica::List<(
        i32,
        (
            metamodelica::Ref<DAE::Exp>,
            metamodelica::Ref<DAE::Exp>,
            metamodelica::Ref<DAE::Exp>,
        ),
    )>,
    i32,
    metamodelica::List<metamodelica::Ref<SimCode::JacobianMatrix>>,
)> {
    let mut delayedExps: metamodelica::List<(
        i32,
        (
            metamodelica::Ref<DAE::Exp>,
            metamodelica::Ref<DAE::Exp>,
            metamodelica::Ref<DAE::Exp>,
        ),
    )> = delayedExps;
    let mut maxDelayedExpIndex: i32 = maxDelayedExpIndex;
    let mut SymJacs: metamodelica::List<metamodelica::Ref<SimCode::JacobianMatrix>> = SymJacs;
    let mut tmpJacs: metamodelica::List<metamodelica::Ref<SimCode::JacobianMatrix>> = metamodelica::nil();
    let mut tmpCols: metamodelica::List<metamodelica::Ref<SimCode::JacobianColumn>>;
    let mut tmpSysts: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
    let mut new_delayedExps: metamodelica::List<metamodelica::Ref<DAE::Exp>>;
    for mut jac in &*SymJacs.reverse() {
        let mut jac = jac.clone();
        tmpCols = metamodelica::nil();
        for mut col in &*jac.columns.clone().reverse() {
            let mut col = col.clone();
            let (__pa0, (_, (__pa1, __pa2))) = traverseExpsEqSystems(
                &col.columnEqns,
                (std::sync::Arc::new(Expression::traverseSubexpressionsHelper)
                    as std::sync::Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, _) -> Result<_> + 'static>),
                (
                    (std::sync::Arc::new(fnptr!(
                        updateDelayExpressions,
                        metamodelica::Ref<DAE::Exp>,
                        (metamodelica::List<metamodelica::Ref<DAE::Exp>>, i32)
                    ))
                        as std::sync::Arc<
                            dyn ::std::ops::Fn(
                                    metamodelica::Ref<DAE::Exp>,
                                    (metamodelica::List<metamodelica::Ref<DAE::Exp>>, i32),
                                ) -> Result<(
                                    metamodelica::Ref<DAE::Exp>,
                                    (metamodelica::List<metamodelica::Ref<DAE::Exp>>, i32),
                                )> + 'static,
                        >),
                    (metamodelica::nil(), maxDelayedExpIndex),
                ),
                metamodelica::nil(),
            )?;
            tmpSysts = metamodelica::Own::own(__pa0);
            new_delayedExps = metamodelica::Own::own(__pa1);
            maxDelayedExpIndex = metamodelica::Own::own(__pa2);
            delayedExps = listAppend(
                List::map(new_delayedExps, &move |__a0: metamodelica::Ref<DAE::Exp>| {
                    extractIdAndExpFromDelayExp(&__a0)
                })?,
                delayedExps,
            );
            assign_field!(col.columnEqns = tmpSysts);
            tmpCols = metamodelica::cons(col, tmpCols);
        }
        assign_field!(jac.columns = tmpCols);
        tmpJacs = metamodelica::cons(jac, tmpJacs);
    }
    SymJacs = tmpJacs;
    Ok((delayedExps, maxDelayedExpIndex, SymJacs))
}

