pub fn createEquationsfromBackendDAE(
    mut inBDAE: &metamodelica::Ref<BackendDAE::BackendDAE>,
    mut iuniqueEqIndex: i32,
    mut itempvars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
    mut genDiscrete: bool,
    mut includeWhen: bool,
    mut skipDiscInZc: bool,
    mut skipDiscInAlgorithm: bool,
) -> Result<(
    metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>,
    i32,
    metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
)> {
    let mut outEquations: metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>> =
        metamodelica::nil();
    let mut uniqueEqIndex: i32 = iuniqueEqIndex;
    let mut tempvars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>> = itempvars;
    let mut comps: metamodelica::List<metamodelica::Ref<BackendDAE::StrongComponent>>;
    let mut simEqs: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
    let mut zeroVarEquations: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
    for mut syst in &*inBDAE.eqs.clone() {
        comps = BackendDAEUtil::getCompsOfMatching(&syst.matching);
        (simEqs, _, uniqueEqIndex, tempvars) = createEquations(
            includeWhen,
            skipDiscInZc,
            genDiscrete,
            skipDiscInAlgorithm,
            metamodelica::AsArg::as_arg(&syst),
            &inBDAE.shared,
            &comps,
            uniqueEqIndex,
            tempvars,
        )?;
        (uniqueEqIndex, zeroVarEquations) = BackendEquation::traverseEquationArray(
            syst.removedEqs.clone(),
            &fnptr!(
                traversedlowEqToSimEqSystem,
                metamodelica::Ref<BackendDAE::Equation>,
                (i32, metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>)
            ),
            (uniqueEqIndex, metamodelica::nil()),
        )?;
        outEquations = metamodelica::cons(listAppend(simEqs, zeroVarEquations), outEquations);
    }
    outEquations = Dangerous::listReverseInPlace(outEquations);
    Ok((outEquations, uniqueEqIndex, tempvars))
}

