fn makeSolved_fromStartValue(
    mut inVar: &metamodelica::Ref<BackendDAE::Var>,
    mut inUniqueEqIndex: i32,
) -> Result<(metamodelica::Ref<SimCode::SimEqSystem>, i32)> {
    let mut outSimEqn: metamodelica::Ref<SimCode::SimEqSystem>;
    let mut outUniqueEqIndex: i32;
    let mut e: metamodelica::Ref<DAE::Exp>;
    let mut varExp: metamodelica::Ref<DAE::Exp>;
    let mut cr: metamodelica::Ref<DAE::ComponentRef>;
    let mut source: metamodelica::Ref<DAE::ElementSource>;
    e = BackendVariable::varBindExpStartValueNoFail(inVar)?;
    source = BackendVariable::getVarSource(inVar);
    if Types::isArray(&inVar.varType) {
        varExp = BackendVariable::varExp(inVar)?;
        outSimEqn = metamodelica::Ref::new(SimCode::SimEqSystem::SES_ARRAY_CALL_ASSIGN {
            index: inUniqueEqIndex,
            lhs: varExp,
            exp: e,
            source: source,
            eqAttr: BackendDAE::EQ_ATTR_DEFAULT_UNKNOWN.clone(),
        });
    } else {
        cr = BackendVariable::varCref(inVar);
        outSimEqn = metamodelica::Ref::new(SimCode::SimEqSystem::SES_SIMPLE_ASSIGN {
            index: inUniqueEqIndex,
            cref: cr,
            exp: e,
            source: source,
            eqAttr: BackendDAE::EQ_ATTR_DEFAULT_UNKNOWN.clone(),
        });
    }
    outUniqueEqIndex = inUniqueEqIndex + 1;
    Ok((outSimEqn, outUniqueEqIndex))
}

