fn preCalculateStartValues(
    mut systIn: metamodelica::Ref<BackendDAE::EqSystem>,
    mut globalKnownVars: BackendDAE::Variables,
    mut shared: metamodelica::Ref<BackendDAE::Shared>,
) -> Result<metamodelica::Ref<BackendDAE::EqSystem>> {
    let mut systOut: metamodelica::Ref<BackendDAE::EqSystem>;
    let mut varMap: metamodelica::List<i32>;
    let mut varMapArr: metamodelica::Array<i32>;
    let mut vars: BackendDAE::Variables;
    let mut vars1: BackendDAE::Variables;
    let mut eqs: metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>>;
    let mut mStart: metamodelica::Array<metamodelica::List<i32>>;
    let mut mTStart: metamodelica::Array<metamodelica::List<i32>>;
    let mut syst: metamodelica::Ref<BackendDAE::EqSystem>;
    let mut varLst: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
    let mut noStartVarLst: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
    let mut stateInfo: metamodelica::List<(i32, BackendDAE::VarKind)>;
    let mut stateIdcs: metamodelica::List<i32>;
    let mut stateKinds: metamodelica::List<BackendDAE::VarKind>;
    vars = systIn.orderedVars.clone();
    stateInfo = List::fold1(
        &(List::intRange(BackendVariable::varsSize(&vars))),
        &move |__a0: i32,
               __a1: BackendDAE::Variables,
               __a2: metamodelica::List<(i32, BackendDAE::VarKind)>|
              -> metamodelica::Result<_> { ::std::result::Result::Ok(getStateInfo(__a0, &__a1, __a2)) },
        vars.clone(),
        metamodelica::nil(),
    )?;
    (vars, _) = BackendVariable::traverseBackendDAEVarsWithUpdate(
        vars,
        (std::sync::Arc::new(setVarKindForStates)
            as std::sync::Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<BackendDAE::Var>,
                        BackendDAE::VarKind,
                    )
                        -> Result<(metamodelica::Ref<BackendDAE::Var>, BackendDAE::VarKind)>
                    + 'static,
            >),
        openmodelica_backend_types::BackendDAE::VarKind::VARIABLE,
    )?;
    varLst = BackendVariable::varList(&vars)?;
    varMap = List::intRange(BackendVariable::varsSize(&vars));
    (noStartVarLst, varMap) = List::filterOnTrueSync(
        &varLst,
        &move |__a0: metamodelica::Ref<BackendDAE::Var>| -> metamodelica::Result<_> {
            ::std::result::Result::Ok(BackendVariable::varHasNoStartValue(&__a0))
        },
        varMap,
    )?;
    eqs = BackendEquation::copyEquationArray(systIn.orderedEqs.clone());
    BackendDAEUtil::traverseBackendDAEExpsEqns(
        eqs.clone(),
        (std::sync::Arc::new(
            move |__a0: metamodelica::Ref<DAE::Exp>, __a1: BackendDAE::Variables| -> metamodelica::Result<_> {
                ::std::result::Result::Ok(replaceCrefWithStartValue(&__a0, &__a1))
            },
        )
            as std::sync::Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<DAE::Exp>,
                        BackendDAE::Variables,
                    ) -> Result<(metamodelica::Ref<DAE::Exp>, BackendDAE::Variables)>
                    + 'static,
            >),
        globalKnownVars,
    )?;
    BackendDAEUtil::traverseBackendDAEExpsEqns(
        eqs.clone(),
        (std::sync::Arc::new(
            move |__a0: metamodelica::Ref<DAE::Exp>, __a1: BackendDAE::Variables| -> metamodelica::Result<_> {
                ::std::result::Result::Ok(replaceCrefWithStartValue(&__a0, &__a1))
            },
        )
            as std::sync::Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<DAE::Exp>,
                        BackendDAE::Variables,
                    ) -> Result<(metamodelica::Ref<DAE::Exp>, BackendDAE::Variables)>
                    + 'static,
            >),
        vars.clone(),
    )?;
    vars1 = BackendVariable::listVar1(&noStartVarLst)?;
    syst = BackendDAEUtil::createEqSystem(
        vars1,
        eqs.clone(),
        metamodelica::nil(),
        openmodelica_backend_types::BackendDAE::BaseClockPartitionKind::UNKNOWN_PARTITION,
        BackendEquation::emptyEqns(),
    );
    (syst, mStart, mTStart) = BackendDAEUtil::getAdjacencyMatrix(
        syst,
        openmodelica_backend_types::BackendDAE::IndexType::NORMAL,
        None,
        BackendDAEUtil::isInitializationDAE(&shared),
    )?;
    varMapArr = metamodelica::arrayFromVec(varMap.into_iter().cloned().collect());
    vars = preCalculateStartValues1(
        List::intRange(metamodelica::arrayLength(mStart.clone())),
        mStart.clone(),
        mTStart.clone(),
        varMapArr.clone(),
        eqs,
        vars,
    )?;
    stateIdcs = List::map(stateInfo.clone(), &fnptr!(Util::tuple21, _))?;
    stateKinds = List::map(stateInfo, &fnptr!(Util::tuple22, _))?;
    vars = List::threadFold(&stateIdcs, stateKinds, &BackendVariable::setVarKindForVar, vars)?;
    (vars, _) = BackendVariable::traverseBackendDAEVarsWithUpdate(
        vars,
        (std::sync::Arc::new(fnptr!(
            evaluateStartValues,
            metamodelica::Ref<BackendDAE::Var>,
            metamodelica::Ref<BackendDAE::Shared>
        ))
            as std::sync::Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<BackendDAE::Var>,
                        metamodelica::Ref<BackendDAE::Shared>,
                    ) -> Result<(
                        metamodelica::Ref<BackendDAE::Var>,
                        metamodelica::Ref<BackendDAE::Shared>,
                    )> + 'static,
            >),
        shared,
    )?;
    systOut = BackendDAEUtil::setEqSystVars(systIn, vars);
    Ok(systOut)
}

