fn dumpFunctions(
    mut functions: &metamodelica::List<metamodelica::Ref<SimCodeFunction::Function::Function>>,
) -> Result<()> {
    let () = (::match_deref::match_deref! { match functions {
        Deref @ metamodelica::ListNode::Nil => {
            ()
        },
        Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCodeFunction::Function::FUNCTION { name: path, outVars, functionArguments, variableDeclarations, .. }, tail: rest } => {
            metamodelica::print({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("Function: ")); __mm_s.push_str(&*AbsynUtil::pathStringNoQual(path.clone(), literal!("."), false, false)?); __mm_s.push_str(&*literal!("\n")); ArcStr::from(__mm_s) });
            metamodelica::print(literal!("\toutVars: "));
            dumpVariablesString(metamodelica::AsArg::as_arg(&outVars), &(literal!(" , ")))?;
            metamodelica::print(literal!("\n\tfunctionArguments: "));
            dumpVariablesString(metamodelica::AsArg::as_arg(&functionArguments), &(literal!(" , ")))?;
            metamodelica::print(literal!("\n\tvariableDeclarations: "));
            dumpVariablesString(metamodelica::AsArg::as_arg(&variableDeclarations), &(literal!(" , ")))?;
            metamodelica::print(literal!("\n"));
            dumpFunctions(rest)?;
            ()
        },
        Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCodeFunction::Function::PARALLEL_FUNCTION { name: path, .. }, tail: rest } => {
            metamodelica::print({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("Parallel Function: ")); __mm_s.push_str(&*AbsynUtil::pathStringNoQual(path.clone(), literal!("."), false, false)?); __mm_s.push_str(&*literal!("\n")); ArcStr::from(__mm_s) });
            dumpFunctions(rest)?;
            ()
        },
        Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCodeFunction::Function::KERNEL_FUNCTION { name: path, .. }, tail: rest } => {
            metamodelica::print({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("Kernel Function: ")); __mm_s.push_str(&*AbsynUtil::pathStringNoQual(path.clone(), literal!("."), false, false)?); __mm_s.push_str(&*literal!("\n")); ArcStr::from(__mm_s) });
            dumpFunctions(rest)?;
            ()
        },
        Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCodeFunction::Function::EXTERNAL_FUNCTION { name: path, outVars, .. }, tail: rest } => {
            metamodelica::print({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("External Function: ")); __mm_s.push_str(&*AbsynUtil::pathStringNoQual(path.clone(), literal!("."), false, false)?); __mm_s.push_str(&*literal!("\n")); ArcStr::from(__mm_s) });
            metamodelica::print(literal!("\toutVars: "));
            dumpVariablesString(metamodelica::AsArg::as_arg(&outVars), &(literal!(" , ")))?;
            metamodelica::print(literal!("\n"));
            dumpFunctions(rest)?;
            ()
        },
        Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCodeFunction::Function::RECORD_CONSTRUCTOR { name: path, funArgs, locals, .. }, tail: rest } => {
            metamodelica::print({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("Record: ")); __mm_s.push_str(&*AbsynUtil::pathStringNoQual(path.clone(), literal!("."), false, false)?); __mm_s.push_str(&*literal!("\n")); ArcStr::from(__mm_s) });
            metamodelica::print(literal!("\tfunArgs: "));
            dumpVariablesString(metamodelica::AsArg::as_arg(&funArgs), &(literal!(" , ")))?;
            metamodelica::print(literal!("\n\tlocals: "));
            dumpVariablesString(metamodelica::AsArg::as_arg(&locals), &(literal!(" , ")))?;
            metamodelica::print(literal!("\n"));
            dumpFunctions(rest)?;
            ()
        },
        _ => return Err("match: no arm matched"),
    } });
    Ok(())
}

pub(crate) fn dumpSimEqSystemLst(
    mut eqSysLstIn: &metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>,
    mut delimiter: ArcStr,
) -> () {
    let mut sys: metamodelica::Ref<SimCode::SimEqSystem> =
        <metamodelica::Ref<SimCode::SimEqSystem> as ::std::default::Default>::default();
    for mut sys in &**eqSysLstIn {
        let mut sys = sys.clone();
        dumpSimEqSystem(&sys);
        metamodelica::print(delimiter.clone());
    }
    ()
}

