fn getFmiUnitDefinitionsHelper(
    mut inVars: &metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
    mut unitDefinitions: metamodelica::List<SimCode::UnitDefinition>,
    mut unitNameKeys: (
        metamodelica::Array<metamodelica::List<(ArcStr, i32)>>,
        (i32, i32, metamodelica::Array<Option<ArcStr>>),
        i32,
        i32,
        (
            Arc<dyn ::std::ops::Fn(ArcStr) -> Result<i32> + 'static>,
            Arc<dyn ::std::ops::Fn(ArcStr, ArcStr) -> Result<bool> + 'static>,
            Arc<dyn ::std::ops::Fn(ArcStr) -> Result<ArcStr> + 'static>,
        ),
    ),
) -> Result<(
    metamodelica::List<SimCode::UnitDefinition>,
    (
        metamodelica::Array<metamodelica::List<(ArcStr, i32)>>,
        (i32, i32, metamodelica::Array<Option<ArcStr>>),
        i32,
        i32,
        (
            Arc<dyn ::std::ops::Fn(ArcStr) -> Result<i32> + 'static>,
            Arc<dyn ::std::ops::Fn(ArcStr, ArcStr) -> Result<bool> + 'static>,
            Arc<dyn ::std::ops::Fn(ArcStr) -> Result<ArcStr> + 'static>,
        ),
    ),
)> {
    let mut unitDefinitions: metamodelica::List<SimCode::UnitDefinition> = unitDefinitions;
    let mut unitNameKeys: (
        metamodelica::Array<metamodelica::List<(ArcStr, i32)>>,
        (i32, i32, metamodelica::Array<Option<ArcStr>>),
        i32,
        i32,
        (
            HashSetString::FuncHashCref,
            HashSetString::FuncCrefEqual,
            HashSetString::FuncCrefStr,
        ),
    ) = unitNameKeys;
    let mut unit: Unit::Unit;
    for mut var in &**inVars {
        if (var.exportVar).is_some() {
            if !(stringEq(&var.unit, &(literal!("")))) && !(BaseHashSet::has(var.unit.clone(), &unitNameKeys)?) {
                unitNameKeys = BaseHashSet::add(var.unit.clone(), &unitNameKeys)?;
                match '__try0: {
                    unit = unwrap_break_err!(Unit::parseUnitString(var.unit.clone(), unwrap_break_err!(Unit::getKnownUnits(), '__try0), &(Absyn::dummyInfo.clone())), '__try0);
                    unitDefinitions = metamodelica::cons(
                        SimCode::UnitDefinition {
                            name: var.unit.clone(),
                            baseUnit: unwrap_break_err!(transformUnitToBaseUnit(unit.clone()), '__try0),
                        },
                        unitDefinitions.clone(),
                    );
                    Ok::<_, &'static str>((unitDefinitions.clone(),))
                } {
                    Ok((__try0_o0,)) => {
                        unitDefinitions = __try0_o0;
                    }
                    Err(_) => {
                        unitDefinitions = metamodelica::cons(
                            SimCode::UnitDefinition {
                                name: var.unit.clone(),
                                baseUnit: openmodelica_simcode_types::SimCode::BaseUnit::NOBASEUNIT,
                            },
                            unitDefinitions.clone(),
                        );
                    }
                }
            }
            if !(stringEq(&var.displayUnit, &(literal!(""))))
                && !(stringEq(&(var.displayUnit.clone()), &(var.unit.clone())))
                && !(BaseHashSet::has(var.displayUnit.clone(), &unitNameKeys)?)
            {
                unitNameKeys = BaseHashSet::add(var.displayUnit.clone(), &unitNameKeys)?;
                unitDefinitions = metamodelica::cons(
                    displayUnitDefinition(var.unit.clone(), var.displayUnit.clone()),
                    unitDefinitions,
                );
            }
        }
    }
    Ok((unitDefinitions, unitNameKeys))
}

