pub fn functionPath(
    mut r#fn: &metamodelica::Ref<SimCodeFunction::Function::Function>,
) -> metamodelica::Ref<Absyn::Path> {
    let mut name: metamodelica::Ref<Absyn::Path>;
    name = (match &**r#fn {
        SimCodeFunction::Function::FUNCTION { name: __esc_name, .. } => {
            name = (*__esc_name).clone();
            name.clone()
        }
        SimCodeFunction::Function::PARALLEL_FUNCTION { name: __esc_name, .. } => {
            name = (*__esc_name).clone();
            name.clone()
        }
        SimCodeFunction::Function::KERNEL_FUNCTION { name: __esc_name, .. } => {
            name = (*__esc_name).clone();
            name.clone()
        }
        SimCodeFunction::Function::EXTERNAL_FUNCTION { name: __esc_name, .. } => {
            name = (*__esc_name).clone();
            name.clone()
        }
        SimCodeFunction::Function::RECORD_CONSTRUCTOR { name: __esc_name, .. } => {
            name = (*__esc_name).clone();
            name.clone()
        }
    });
    name
}

fn adjustStatesForInlineSolver(
    mut inStates: &metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
) -> Result<metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>> {
    let mut outStates: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>> = metamodelica::nil();
    match '__try0: {
        for mut var in &**inStates {
            let mut var = var.clone();
            assign_field!(
                var.name = unwrap_break_err!(ComponentReference::appendStringLastIdent(&(literal!("$Old")), &var.name), '__try0),
                var.varKind = openmodelica_backend_types::BackendDAE::VarKind::ALG_STATE_OLD
            );
            outStates = metamodelica::cons(var.clone(), outStates.clone());
        }
        Ok::<(), &'static str>(())
    } {
        Ok(()) => {}
        Err(__try0_err) => {
            Error::addMessage(
                Error::INTERNAL_ERROR.clone(),
                list![literal!("SimCodeUtil.adjustStatesForInlineSolver failed")],
            )?;
            return Err(__try0_err);
        }
    }
    Ok(outStates)
}

