/* ******** for dimension *******/
fn calculateVariableDimensions<'__b>(
    mut in_vars: &'__b metamodelica::List<(metamodelica::Ref<DAE::ComponentRef>, i32)>,
    mut inNvar1: i32,
    mut inNvar2: i32,
) -> (i32, i32) {
    '__tco: loop {
        ::match_deref::match_deref! { match in_vars {
            Deref @ metamodelica::ListNode::Nil => {
                return (inNvar1, inNvar2)
            },
            Deref @ metamodelica::ListNode::Cons { head: (_, 0), tail: rest } => {
                { (in_vars, inNvar1, inNvar2) = (rest, inNvar1 + 1, inNvar2); continue '__tco; }
            },
            Deref @ metamodelica::ListNode::Cons { head: (_, _), tail: rest } => {
                { (in_vars, inNvar1, inNvar2) = (rest, inNvar1, inNvar2 + 1); continue '__tco; }
            },
            _ => unreachable!("tail-call lowered match: no arm matched"),
        } }
    }
}

