fn compareSimVarName(
    mut var1: &metamodelica::Ref<SimCodeVar::SimVar>,
    mut var2: &metamodelica::Ref<SimCodeVar::SimVar>,
) -> Result<bool> {
    let mut result: bool;
    let mut name1: metamodelica::Ref<DAE::ComponentRef>;
    let mut name2: metamodelica::Ref<DAE::ComponentRef>;
    let __arc1 = &(*var1);
    let SimCodeVar::SIMVAR { name: __pa0, .. } = &**__arc1;
    name1 = metamodelica::Own::own(__pa0);
    let __arc3 = &(*var2);
    let SimCodeVar::SIMVAR { name: __pa2, .. } = &**__arc3;
    name2 = metamodelica::Own::own(__pa2);
    result = ComponentReferenceBasics::crefEqual(&name1, &name2)?;
    Ok(result)
}

pub(crate) fn compareVarIndexGt(
    mut var1: &metamodelica::Ref<SimCodeVar::SimVar>,
    mut var2: &metamodelica::Ref<SimCodeVar::SimVar>,
) -> Result<bool> {
    let mut result: bool;
    let mut index1: i32;
    let mut index2: i32;
    let __pa0 = ::match_deref::match_deref! { match &((*var1)) {
        Deref @ SimCodeVar::SimVar { variable_index: Some(__pa0), .. } => __pa0.clone(),
        _ => return Err("pattern mismatch"),
    } };
    index1 = metamodelica::Own::own(__pa0);
    let __pa1 = ::match_deref::match_deref! { match &((*var2)) {
        Deref @ SimCodeVar::SimVar { variable_index: Some(__pa1), .. } => __pa1.clone(),
        _ => return Err("pattern mismatch"),
    } };
    index2 = metamodelica::Own::own(__pa1);
    result = index1 > index2;
    Ok(result)
}

pub(crate) fn compareSimVarTupleIndexGt<anyT: Clone + 'static + metamodelica::gc::MMTrace>(
    mut var1: &(metamodelica::Ref<SimCodeVar::SimVar>, anyT),
    mut var2: &(metamodelica::Ref<SimCodeVar::SimVar>, anyT),
) -> Result<bool> {
    let mut result: bool;
    let mut index1: i32;
    let mut index2: i32;
    let __pa0 = ::match_deref::match_deref! { match var1 {
        (Deref @ SimCodeVar::SimVar { variable_index: Some(__pa0), .. }, _) => __pa0.clone(),
        _ => return Err("pattern mismatch"),
    } };
    index1 = metamodelica::Own::own(__pa0);
    let __pa2 = ::match_deref::match_deref! { match var2 {
        (Deref @ SimCodeVar::SimVar { variable_index: Some(__pa2), .. }, _) => __pa2.clone(),
        _ => return Err("pattern mismatch"),
    } };
    index2 = metamodelica::Own::own(__pa2);
    result = index1 > index2;
    Ok(result)
}

fn getFilesFromSimVar(
    mut var: metamodelica::Ref<SimCodeVar::SimVar>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> (
    metamodelica::Ref<SimCodeVar::SimVar>,
    metamodelica::List<SimCode::FileInfo>,
) {
    let mut var: metamodelica::Ref<SimCodeVar::SimVar> = var;
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    outFiles = getFilesFromDAEElementSource(&var.source, inFiles);
    (var, outFiles)
}

fn getFilesFromSimVars(
    mut inSimVars: &SimCodeVar::SimVars,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    outFiles = (match inSimVars.clone() {
        SimCodeVar::SimVars {
            stateVars: mut stateVars,
            derivativeVars: mut derivativeVars,
            algVars: mut algVars,
            discreteAlgVars: mut discreteAlgVars,
            intAlgVars: mut intAlgVars,
            boolAlgVars: mut boolAlgVars,
            inputVars: mut inputVars,
            outputVars: mut outputVars,
            aliasVars: mut aliasVars,
            intAliasVars: mut intAliasVars,
            boolAliasVars: mut boolAliasVars,
            paramVars: mut paramVars,
            intParamVars: mut intParamVars,
            boolParamVars: mut boolParamVars,
            stringAlgVars: mut stringAlgVars,
            stringParamVars: mut stringParamVars,
            stringAliasVars: mut stringAliasVars,
            extObjVars: mut extObjVars,
            constVars: mut constVars,
            intConstVars: mut intConstVars,
            boolConstVars: mut boolConstVars,
            stringConstVars: mut stringConstVars,
            jacobianVars: mut jacobianVars,
            seedVars: mut seedVars,
            realOptimizeConstraintsVars: mut realOptimizeConstraintsVars,
            realOptimizeFinalConstraintsVars: mut realOptimizeFinalConstraintsVars,
            sensitivityVars: mut sensitivityVars,
            ..
        } => {
            let mut files = inFiles;
            (_, files) = List::mapFoldList(
                &(list![
                    stateVars.clone(),
                    derivativeVars.clone(),
                    algVars.clone(),
                    discreteAlgVars.clone(),
                    intAlgVars.clone(),
                    boolAlgVars.clone(),
                    inputVars.clone(),
                    outputVars.clone(),
                    aliasVars.clone(),
                    intAliasVars.clone(),
                    boolAliasVars.clone(),
                    paramVars.clone(),
                    intParamVars.clone(),
                    boolParamVars.clone(),
                    stringAlgVars.clone(),
                    stringParamVars.clone(),
                    stringAliasVars.clone(),
                    extObjVars.clone(),
                    constVars.clone(),
                    intConstVars.clone(),
                    boolConstVars.clone(),
                    stringConstVars.clone(),
                    jacobianVars.clone(),
                    seedVars.clone(),
                    realOptimizeConstraintsVars.clone(),
                    realOptimizeFinalConstraintsVars.clone(),
                    sensitivityVars.clone()
                ]),
                &fnptr!(
                    getFilesFromSimVar,
                    metamodelica::Ref<SimCodeVar::SimVar>,
                    metamodelica::List<SimCode::FileInfo>
                ),
                files,
            )?;
            files
        }
    });
    Ok(outFiles)
}

fn getFilesFromFunctions(
    mut functions: metamodelica::List<metamodelica::Ref<SimCodeFunction::Function::Function>>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    '__tco: loop {
        ::match_deref::match_deref! { match &((functions, inFiles)) {
            (Deref @ metamodelica::ListNode::Nil, files) => {
                return Ok(files.clone())
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCodeFunction::Function::FUNCTION { info, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromAbsynInfo(metamodelica::AsArg::as_arg(&info), files.clone());
                { (functions, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCodeFunction::Function::EXTERNAL_FUNCTION { info, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromAbsynInfo(metamodelica::AsArg::as_arg(&info), files.clone());
                { (functions, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCodeFunction::Function::RECORD_CONSTRUCTOR { info, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromAbsynInfo(metamodelica::AsArg::as_arg(&info), files.clone());
                { (functions, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            _ => return Err("match: no arm matched"),
        } }
    }
}

fn getFilesFromSimEqSystemOpt(
    mut inSimEqSystemOpt: Option<metamodelica::Ref<SimCode::SimEqSystem>>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    outFiles = (::match_deref::match_deref! { match &(inSimEqSystemOpt) {
        None => {
            let mut files = inFiles;
            files
        },
        Some(sys) => {
            let mut files = inFiles;
            (_, files) = getFilesFromSimEqSystem(sys.clone(), files)?;
            files
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(outFiles)
}

fn getFilesFromSimEqSystem(
    mut inSimEqSystem: metamodelica::Ref<SimCode::SimEqSystem>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<(
    metamodelica::Ref<SimCode::SimEqSystem>,
    metamodelica::List<SimCode::FileInfo>,
)> {
    let mut outSimEqSystem: metamodelica::Ref<SimCode::SimEqSystem>;
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    (outSimEqSystem, outFiles) = (::match_deref::match_deref! { match &(inSimEqSystem.clone()) {
        Deref @ SimCode::SimEqSystem::SES_RESIDUAL { source, .. } => {
            let mut files = inFiles;
            files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files);
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_FOR_RESIDUAL { source, .. } => {
            let mut files = inFiles;
            files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files);
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_GENERIC_RESIDUAL { source, .. } => {
            let mut files = inFiles;
            files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files);
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_SIMPLE_ASSIGN { source, .. } => {
            let mut files = inFiles;
            files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files);
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_SIMPLE_ASSIGN_CONSTRAINTS { source, .. } => {
            let mut files = inFiles;
            files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files);
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_ARRAY_CALL_ASSIGN { source, .. } => {
            let mut files = inFiles;
            files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files);
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_ALGORITHM { statements, .. } => {
            let mut files = inFiles;
            files = getFilesFromStatements(statements.clone(), files)?;
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_INVERSE_ALGORITHM { statements, .. } => {
            let mut files = inFiles;
            files = getFilesFromStatements(statements.clone(), files)?;
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_LINEAR { lSystem: Deref @ SimCode::LinearSystem { vars, simJac, .. }, .. } => {
            let mut files = inFiles;
            let mut systems: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
            (_, files) = List::mapFold(metamodelica::AsArg::as_arg(&vars), &fnptr!(getFilesFromSimVar, metamodelica::Ref<SimCodeVar::SimVar>, metamodelica::List<SimCode::FileInfo>), files)?;
            systems = List::map(simJac.clone(), &fnptr!(Util::tuple33, _))?;
            files = getFilesFromSimEqSystems(&(list![systems]), files)?;
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_NONLINEAR { nlSystem: Deref @ SimCode::NonlinearSystem { eqs: systems, .. }, .. } => {
            let mut files = inFiles;
            files = getFilesFromSimEqSystems(&(list![systems.clone()]), files)?;
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_MIXED { cont: system, discVars: vars, discEqs: systems, .. } => {
            let mut files = inFiles;
            (_, files) = List::mapFold(metamodelica::AsArg::as_arg(&vars), &fnptr!(getFilesFromSimVar, metamodelica::Ref<SimCodeVar::SimVar>, metamodelica::List<SimCode::FileInfo>), files)?;
            files = getFilesFromSimEqSystems(&(list![metamodelica::cons(system.clone(), systems.clone())]), files)?;
            (inSimEqSystem, files)
        },
        Deref @ SimCode::SimEqSystem::SES_WHEN { source, whenStmtLst, elseWhen: systemOpt, .. } => {
            let mut files = inFiles;
            files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files);
            files = getFilesFromWhenOperators(whenStmtLst.clone(), files)?;
            files = getFilesFromSimEqSystemOpt(systemOpt.clone(), files)?;
            (inSimEqSystem, files)
        },
        _ => return Err("match: no arm matched"),
    } });
    Ok((outSimEqSystem, outFiles))
}

fn getFilesFromSimEqSystems(
    mut inSimEqSystems: &metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    (_, outFiles) = List::mapFoldList(inSimEqSystems, &getFilesFromSimEqSystem, inFiles)?;
    Ok(outFiles)
}

fn getFilesFromStatementsElse(
    mut inElse: metamodelica::Ref<DAE::Else>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    '__tco: loop {
        ::match_deref::match_deref! { match &((inElse, inFiles)) {
            (Deref @ DAE::Else::NOELSE { .. }, files) => {
                return Ok(files.clone())
            },
            (Deref @ DAE::Else::ELSEIF { statementLst: stmts, else_: elsePart, .. }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromStatements(stmts.clone(), files.clone())?;
                { (inElse, inFiles) = (elsePart.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ DAE::Else::ELSE { statementLst: stmts }, files) => {
                let mut files = (*files).clone();
                return Ok(getFilesFromStatements(stmts.clone(), files.clone())?)
            },
            _ => return Err("match: no arm matched"),
        } }
    }
}

fn getFilesFromStatementsElseWhen(
    mut inStatementOpt: Option<metamodelica::Ref<DAE::Statement>>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    outFiles = (::match_deref::match_deref! { match &(inStatementOpt) {
        None => {
            let mut files = inFiles;
            files
        },
        Some(stmt) => {
            let mut files = inFiles;
            getFilesFromStatements(list![stmt.clone()], files)?
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(outFiles)
}

fn getFilesFromStatements(
    mut inStatements: metamodelica::List<metamodelica::Ref<DAE::Statement>>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    '__tco: loop {
        ::match_deref::match_deref! { match &((inStatements, inFiles)) {
            (Deref @ metamodelica::ListNode::Nil, files) => {
                return Ok(files.clone())
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_ASSIGN { source, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_TUPLE_ASSIGN { source, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_ASSIGN_ARR { source, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_IF { source, statementLst: stmts, else_: elsePart, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                files = getFilesFromStatements(stmts.clone(), files.clone())?;
                files = getFilesFromStatementsElse(elsePart.clone(), files.clone())?;
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_FOR { source, statementLst: stmts, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                files = getFilesFromStatements(stmts.clone(), files.clone())?;
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_PARFOR { source, statementLst: stmts, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                files = getFilesFromStatements(stmts.clone(), files.clone())?;
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_WHILE { source, statementLst: stmts, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                files = getFilesFromStatements(stmts.clone(), files.clone())?;
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_WHEN { source, statementLst: stmts, elseWhen, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                files = getFilesFromStatements(stmts.clone(), files.clone())?;
                files = getFilesFromStatementsElseWhen(elseWhen.clone(), files.clone())?;
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_ASSERT { source, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_TERMINATE { source, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_REINIT { source, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_NORETCALL { source, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_RETURN { source }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_BREAK { source }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_FAILURE { source, body: stmts }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromDAEElementSource(metamodelica::AsArg::as_arg(&source), files.clone());
                files = getFilesFromStatements(stmts.clone(), files.clone())?;
                { (inStatements, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            _ => return Err("match: no arm matched"),
        } }
    }
}

