fn getFilesFromExtObjInfo(
    mut inExtObjInfo: &SimCode::ExtObjInfo,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    (_, outFiles) = List::mapFold(
        &inExtObjInfo.vars,
        &fnptr!(
            getFilesFromSimVar,
            metamodelica::Ref<SimCodeVar::SimVar>,
            metamodelica::List<SimCode::FileInfo>
        ),
        inFiles,
    )?;
    Ok(outFiles)
}

fn getFilesFromJacobianMatrices(
    mut inJacobianMatrices: metamodelica::List<metamodelica::Ref<SimCode::JacobianMatrix>>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    '__tco: loop {
        ::match_deref::match_deref! { match &((inJacobianMatrices, inFiles)) {
            (Deref @ metamodelica::ListNode::Nil, files) => {
                return Ok(files.clone())
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCode::JacobianMatrix { columns: onemat, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromJacobianMatrix(onemat.clone(), files.clone())?;
                { (inJacobianMatrices, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            _ => return Err("match: no arm matched"),
        } }
    }
}

fn getFilesFromJacobianMatrix(
    mut inJacobianMatrices: metamodelica::List<metamodelica::Ref<SimCode::JacobianColumn>>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> Result<metamodelica::List<SimCode::FileInfo>> {
    '__tco: loop {
        ::match_deref::match_deref! { match &((inJacobianMatrices, inFiles)) {
            (Deref @ metamodelica::ListNode::Nil, files) => {
                return Ok(files.clone())
            },
            (Deref @ metamodelica::ListNode::Cons { head: Deref @ SimCode::JacobianColumn { columnEqns: systems, columnVars: vars, .. }, tail: rest }, files) => {
                let mut files = (*files).clone();
                files = getFilesFromSimEqSystems(&(list![systems.clone()]), files.clone())?;
                (_, files) = List::mapFold(metamodelica::AsArg::as_arg(&vars), &fnptr!(getFilesFromSimVar, metamodelica::Ref<SimCodeVar::SimVar>, metamodelica::List<SimCode::FileInfo>), files.clone())?;
                { (inJacobianMatrices, inFiles) = (rest.clone(), files.clone()); continue '__tco; }
            },
            _ => return Err("match: no arm matched"),
        } }
    }
}

fn collectAllFiles(mut inSimCode: metamodelica::Ref<SimCode::SimCode>) -> Result<metamodelica::Ref<SimCode::SimCode>> {
    let mut outSimCode: metamodelica::Ref<SimCode::SimCode> = inSimCode;
    let mut modelInfo: SimCode::ModelInfo;
    let mut files: metamodelica::List<SimCode::FileInfo> = metamodelica::nil();
    if !(Config::acceptMetaModelicaGrammar()?) {
        modelInfo = outSimCode.modelInfo.clone();
        files = getFilesFromSimVars(&modelInfo.vars, files)?;
        files = getFilesFromFunctions(modelInfo.functions.clone(), files)?;
        files = getFilesFromSimEqSystems(
            &(metamodelica::cons(
                outSimCode.allEquations.clone(),
                metamodelica::cons(
                    outSimCode.startValueEquations.clone(),
                    metamodelica::cons(
                        outSimCode.nominalValueEquations.clone(),
                        metamodelica::cons(
                            outSimCode.minValueEquations.clone(),
                            metamodelica::cons(
                                outSimCode.maxValueEquations.clone(),
                                metamodelica::cons(
                                    outSimCode.parameterEquations.clone(),
                                    metamodelica::cons(
                                        outSimCode.removedEquations.clone(),
                                        metamodelica::cons(
                                            outSimCode.algorithmAndEquationAsserts.clone(),
                                            outSimCode.odeEquations.clone(),
                                        ),
                                    ),
                                ),
                            ),
                        ),
                    ),
                ),
            )),
            files,
        )?;
        files = getFilesFromSimEqSystems(&outSimCode.algebraicEquations, files)?;
        files = getFilesFromExtObjInfo(&outSimCode.extObjInfo, files)?;
        files = getFilesFromJacobianMatrices(outSimCode.jacobianMatrices.clone(), files)?;
        files = List::sort(
            files,
            (std::sync::Arc::new(fnptr!(greaterFileInfo, SimCode::FileInfo, SimCode::FileInfo))
                as std::sync::Arc<dyn ::std::ops::Fn(SimCode::FileInfo, SimCode::FileInfo) -> Result<bool> + 'static>),
        )?;
        assign_field!(outSimCode.modelInfo = modelInfo);
    }
    Ok(outSimCode)
}

fn getFilesFromDAEElementSource(
    mut inSource: &metamodelica::Ref<DAE::ElementSource>,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> metamodelica::List<SimCode::FileInfo> {
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    outFiles = getFilesFromAbsynInfo(&inSource.info, inFiles);
    outFiles
}

fn getFilesFromAbsynInfo(
    mut inInfo: &SourceInfo,
    mut inFiles: metamodelica::List<SimCode::FileInfo>,
) -> metamodelica::List<SimCode::FileInfo> {
    let mut outFiles: metamodelica::List<SimCode::FileInfo>;
    let mut fi: SimCode::FileInfo;
    fi = SimCode::FileInfo {
        fileName: inInfo.fileName.clone(),
        isReadOnly: inInfo.isReadOnly.clone(),
    };
    outFiles = List::consOnTrue(!(listMember(fi.clone(), inFiles.clone())), fi, inFiles);
    outFiles
}

fn equalFileInfo(mut inFileInfo1: SimCode::FileInfo, mut inFileInfo2: SimCode::FileInfo) -> bool {
    let mut isMatch: bool;
    let mut f1: ArcStr;
    let mut f2: ArcStr;
    let SimCode::FILEINFO {
        fileName: __pa0,
        isReadOnly: _,
    } = inFileInfo1;
    f1 = metamodelica::Own::own(__pa0);
    let SimCode::FILEINFO {
        fileName: __pa1,
        isReadOnly: _,
    } = inFileInfo2;
    f2 = metamodelica::Own::own(__pa1);
    isMatch = stringEq(&f1, &f2);
    isMatch
}

fn greaterFileInfo(mut inFileInfo1: SimCode::FileInfo, mut inFileInfo2: SimCode::FileInfo) -> bool {
    let mut isGreater: bool;
    let mut f1: ArcStr;
    let mut f2: ArcStr;
    let mut compare: i32;
    let SimCode::FILEINFO {
        fileName: __pa0,
        isReadOnly: _,
    } = inFileInfo1;
    f1 = metamodelica::Own::own(__pa0);
    let SimCode::FILEINFO {
        fileName: __pa1,
        isReadOnly: _,
    } = inFileInfo2;
    f2 = metamodelica::Own::own(__pa1);
    compare = stringCompare(&f1, &f2);
    isGreater = intGt(compare, 0);
    isGreater
}

fn getFileIndexFromFiles(mut file: ArcStr, mut files: &metamodelica::List<SimCode::FileInfo>) -> Result<i32> {
    let mut index: i32;
    index = List::position1OnTrue(
        files,
        &fnptr!(equalFileInfo, SimCode::FileInfo, SimCode::FileInfo),
        SimCode::FileInfo {
            fileName: file,
            isReadOnly: false,
        },
    )? - 1;
    Ok(index)
}

pub(crate) fn fileName2fileIndex(mut inFileName: ArcStr, mut inFiles: metamodelica::List<SimCode::FileInfo>) -> i32 {
    let mut outFileIndex: i32;
    outFileIndex = 'mc: {
        let __mc_input = (inFileName, inFiles);
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (file, files) => {
                    let mut index: i32;
                    index = getFileIndexFromFiles(file.clone(), metamodelica::AsArg::as_arg(&files))?;
                    Ok(index)
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                _ => {
                    Ok(-1)
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        panic!("matchcontinue: no arm matched")
    };
    outFileIndex
}

fn makeEqualLengthLists(
    mut inLst: metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>,
    mut i: i32,
) -> Result<metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>> {
    let mut olst: metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>;
    olst = 'mc: {
        let __mc_input = (inLst, i);
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (lst, _) => {
                    let mut l: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
                    let false = (Flags::isSet(Flags::PTHREADS.clone())?) else { return Err("pattern mismatch") };
                    l = List::flatten(lst.clone())?;
                    Ok(metamodelica::cons(l.clone(), metamodelica::nil()))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (lst, 0) => {
                    Ok(lst.clone())
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (lst, 1) => {
                    let mut l: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
                    l = List::flatten(lst.clone())?;
                    Ok(metamodelica::cons(l.clone(), metamodelica::nil()))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (lst, _) => {
                    let mut q: metamodelica::List<metamodelica::Ref<PriorityQueue::Tree>>;
                    let mut prios: metamodelica::List<(i32, metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>)>;
                    let mut lst = (*lst).clone();
                    q = List::fold(&(List::fill((0, metamodelica::nil()), i)), &PriorityQueue::insert, PriorityQueue::empty().clone())?;
                    prios = List::map(lst.clone(), &calcPriority)?;
                    q = List::fold(&prios, &move |__a0: (i32, metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>), __a1: metamodelica::List<metamodelica::Ref<PriorityQueue::Tree>>| makeEqualLengthLists2(&__a0, __a1), q.clone())?;
                    lst = List::map(PriorityQueue::elements(q.clone())?, &fnptr!(Util::tuple22, _))?;
                    Ok(lst.clone())
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        return Err("matchcontinue: no arm matched");
    };
    Ok(olst)
}

fn makeEqualLengthLists2(
    mut elt: &(i32, metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>),
    mut iq: metamodelica::List<metamodelica::Ref<PriorityQueue::Tree>>,
) -> Result<metamodelica::List<metamodelica::Ref<PriorityQueue::Tree>>> {
    let mut oq: metamodelica::List<metamodelica::Ref<PriorityQueue::Tree>>;
    oq = (::match_deref::match_deref! { match &(elt) {
        (i1, l1) => {
            let mut q = iq;
            let mut l2: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
            let mut i2: i32;
            let (__pa0, (__pa1, __pa2)) = PriorityQueue::deleteAndReturnMin(&q)?;
            q = metamodelica::Own::own(__pa0);
            i2 = metamodelica::Own::own(__pa1);
            l2 = metamodelica::Own::own(__pa2);
            q = PriorityQueue::insert((i1.clone() + i2, listAppend(l2, l1.clone())), q)?;
            q
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(oq)
}

fn calcPriority(
    mut eqs: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>,
) -> Result<(i32, metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>)> {
    let mut prio: (i32, metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>);
    let mut i: i32;
    (_, i) = traverseExpsEqSystems(
        &eqs,
        (std::sync::Arc::new(Expression::complexityTraverse)
            as std::sync::Arc<
                dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, i32) -> Result<(metamodelica::Ref<DAE::Exp>, i32)>
                    + 'static,
            >),
        1,
        metamodelica::nil(),
    )?;
    prio = (i, eqs);
    Ok(prio)
}

pub fn findSimCodeLiterals(
    mut simCode: metamodelica::Ref<SimCode::SimCode>,
    mut inLiterals: (
        i32,
        (
            metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::Exp>, i32)>>,
            (
                i32,
                i32,
                metamodelica::Array<Option<(metamodelica::Ref<DAE::Exp>, i32)>>,
            ),
            i32,
            (
                Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<i32> + 'static>,
                Arc<
                    dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, metamodelica::Ref<DAE::Exp>) -> Result<bool>
                        + 'static,
                >,
                Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<ArcStr> + 'static>,
                Arc<dyn ::std::ops::Fn(i32) -> Result<ArcStr> + 'static>,
            ),
        ),
        metamodelica::List<metamodelica::Ref<DAE::Exp>>,
    ),
) -> Result<(
    metamodelica::Ref<SimCode::SimCode>,
    metamodelica::List<metamodelica::Ref<DAE::Exp>>,
)> {
    let mut simCode: metamodelica::Ref<SimCode::SimCode> = simCode;
    let mut literals: metamodelica::List<metamodelica::Ref<DAE::Exp>>;
    let mut uses: (
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::Exp>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<Option<(metamodelica::Ref<DAE::Exp>, i32)>>,
        ),
        i32,
        (
            HashTableExpToIndex::FuncHashCref,
            HashTableExpToIndex::FuncCrefEqual,
            HashTableExpToIndex::FuncCrefStr,
            HashTableExpToIndex::FuncExpStr,
        ),
    );
    (_, uses) = traverseExpsSimCode(
        simCode.clone(),
        (std::sync::Arc::new(SimCodeFunctionUtil::countStringUses)
            as std::sync::Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<DAE::Exp>,
                        (
                            metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::Exp>, i32)>>,
                            (
                                i32,
                                i32,
                                metamodelica::Array<Option<(metamodelica::Ref<DAE::Exp>, i32)>>,
                            ),
                            i32,
                            (
                                Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<i32> + 'static>,
                                Arc<
                                    dyn ::std::ops::Fn(
                                            metamodelica::Ref<DAE::Exp>,
                                            metamodelica::Ref<DAE::Exp>,
                                        ) -> Result<bool>
                                        + 'static,
                                >,
                                Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<ArcStr> + 'static>,
                                Arc<dyn ::std::ops::Fn(i32) -> Result<ArcStr> + 'static>,
                            ),
                        ),
                    ) -> Result<(
                        metamodelica::Ref<DAE::Exp>,
                        (
                            metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::Exp>, i32)>>,
                            (
                                i32,
                                i32,
                                metamodelica::Array<Option<(metamodelica::Ref<DAE::Exp>, i32)>>,
                            ),
                            i32,
                            (
                                Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<i32> + 'static>,
                                Arc<
                                    dyn ::std::ops::Fn(
                                            metamodelica::Ref<DAE::Exp>,
                                            metamodelica::Ref<DAE::Exp>,
                                        ) -> Result<bool>
                                        + 'static,
                                >,
                                Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<ArcStr> + 'static>,
                                Arc<dyn ::std::ops::Fn(i32) -> Result<ArcStr> + 'static>,
                            ),
                        ),
                    )> + 'static,
            >),
        HashTableExpToIndex::emptyHashTableSized(BaseHashTable::bigBucketSize.clone()),
    )?;
    let (__pa0, (_, _, __pa1)) = traverseExpsSimCode(
        simCode,
        (std::sync::Arc::new({
            let __pe_b1 = uses;
            move |__pe_a0, __pe_a2| SimCodeFunctionUtil::findLiteralsHelperKeepSingle(__pe_a0, &__pe_b1, __pe_a2)
        })
            as std::sync::Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<DAE::Exp>,
                        (
                            i32,
                            (
                                metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::Exp>, i32)>>,
                                (
                                    i32,
                                    i32,
                                    metamodelica::Array<Option<(metamodelica::Ref<DAE::Exp>, i32)>>,
                                ),
                                i32,
                                (
                                    Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<i32> + 'static>,
                                    Arc<
                                        dyn ::std::ops::Fn(
                                                metamodelica::Ref<DAE::Exp>,
                                                metamodelica::Ref<DAE::Exp>,
                                            ) -> Result<bool>
                                            + 'static,
                                    >,
                                    Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<ArcStr> + 'static>,
                                    Arc<dyn ::std::ops::Fn(i32) -> Result<ArcStr> + 'static>,
                                ),
                            ),
                            metamodelica::List<metamodelica::Ref<DAE::Exp>>,
                        ),
                    ) -> Result<(
                        metamodelica::Ref<DAE::Exp>,
                        (
                            i32,
                            (
                                metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::Exp>, i32)>>,
                                (
                                    i32,
                                    i32,
                                    metamodelica::Array<Option<(metamodelica::Ref<DAE::Exp>, i32)>>,
                                ),
                                i32,
                                (
                                    Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<i32> + 'static>,
                                    Arc<
                                        dyn ::std::ops::Fn(
                                                metamodelica::Ref<DAE::Exp>,
                                                metamodelica::Ref<DAE::Exp>,
                                            ) -> Result<bool>
                                            + 'static,
                                    >,
                                    Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>) -> Result<ArcStr> + 'static>,
                                    Arc<dyn ::std::ops::Fn(i32) -> Result<ArcStr> + 'static>,
                                ),
                            ),
                            metamodelica::List<metamodelica::Ref<DAE::Exp>>,
                        ),
                    )> + 'static,
            >),
        inLiterals,
    )?;
    simCode = metamodelica::Own::own(__pa0);
    literals = metamodelica::Own::own(__pa1);
    literals = literals.reverse();
    Ok((simCode, literals))
}

pub(crate) fn traverseExpsSimCode<A: Clone + 'static + metamodelica::gc::MMTrace>(
    mut simCode: metamodelica::Ref<SimCode::SimCode>,
    mut func: Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >,
    mut ia: A,
) -> Result<(metamodelica::Ref<SimCode::SimCode>, A)> {
    pub type Func<A: Clone + 'static> = std::sync::Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >;

    let mut outSimCode: metamodelica::Ref<SimCode::SimCode> = simCode;
    let mut oa: A;
    let mut literals: metamodelica::List<metamodelica::Ref<DAE::Exp>>;
    let mut eqs: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
    let mut eqs1: metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>;
    let mut partitions: metamodelica::List<SimCode::ClockedPartition>;
    (literals, oa) = List::mapFold(&outSimCode.literals, &*func, ia)?;
    assign_field!(outSimCode.literals = literals);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.allEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.allEquations = eqs);
    (partitions, oa) = List::map1Fold(&outSimCode.clockedPartitions, &traverseExpsPartition, func.clone(), oa)?;
    assign_field!(outSimCode.clockedPartitions = partitions);
    (eqs1, oa) = traverseExpsEqSystemsList(outSimCode.odeEquations.clone(), func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.odeEquations = eqs1);
    (eqs1, oa) = traverseExpsEqSystemsList(
        outSimCode.algebraicEquations.clone(),
        func.clone(),
        oa,
        metamodelica::nil(),
    )?;
    assign_field!(outSimCode.algebraicEquations = eqs1);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.initialEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.initialEquations = eqs);
    (eqs, oa) = traverseExpsEqSystems(
        &outSimCode.removedInitialEquations,
        func.clone(),
        oa,
        metamodelica::nil(),
    )?;
    assign_field!(outSimCode.removedInitialEquations = eqs);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.startValueEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.startValueEquations = eqs);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.nominalValueEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.nominalValueEquations = eqs);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.minValueEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.minValueEquations = eqs);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.maxValueEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.maxValueEquations = eqs);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.parameterEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.parameterEquations = eqs);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.removedEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.removedEquations = eqs);
    (eqs, oa) = traverseExpsEqSystems(
        &outSimCode.algorithmAndEquationAsserts,
        func.clone(),
        oa,
        metamodelica::nil(),
    )?;
    assign_field!(outSimCode.algorithmAndEquationAsserts = eqs);
    (eqs, oa) = traverseExpsEqSystems(&outSimCode.jacobianEquations, func.clone(), oa, metamodelica::nil())?;
    assign_field!(outSimCode.jacobianEquations = eqs);
    Ok((outSimCode, oa))
}

fn traverseExpsPartition<A: Clone + 'static + metamodelica::gc::MMTrace>(
    mut simPartition: SimCode::ClockedPartition,
    mut func: Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >,
    mut ia: A,
) -> Result<(SimCode::ClockedPartition, A)> {
    pub type Func<A: Clone + 'static> = std::sync::Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >;

    let mut outSimPartition: SimCode::ClockedPartition = simPartition.clone();
    let mut oa: A;
    let mut clk: metamodelica::Ref<DAE::ClockKind>;
    let mut subPartitions: metamodelica::List<SimCode::SubPartition>;
    let (__pa0, __pa1) = ::match_deref::match_deref! { match &(func(metamodelica::Ref::new(DAE::Exp::CLKCONST { clk: simPartition.baseClock.clone() }), ia)?) {
        (Deref @ DAE::Exp::CLKCONST { clk: __pa0 }, __pa1) => (__pa0.clone(), __pa1.clone()),
        _ => return Err("pattern mismatch"),
    } };
    clk = metamodelica::Own::own(__pa0);
    oa = metamodelica::Own::own(__pa1);
    (subPartitions, oa) = List::map1Fold(&simPartition.subPartitions, &traverseExpsSubPartition, func.clone(), oa)?;
    outSimPartition.baseClock = clk;
    outSimPartition.subPartitions = subPartitions;
    Ok((outSimPartition, oa))
}

fn traverseExpsSubPartition<A: Clone + 'static + metamodelica::gc::MMTrace>(
    mut subPartition: SimCode::SubPartition,
    mut func: Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >,
    mut ia: A,
) -> Result<(SimCode::SubPartition, A)> {
    pub type Func<A: Clone + 'static> = std::sync::Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >;

    let mut outSubPartition: SimCode::SubPartition = subPartition.clone();
    let mut oa: A;
    let mut eqs: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
    (eqs, oa) = traverseExpsEqSystems(&subPartition.equations, func.clone(), ia, metamodelica::nil())?;
    outSubPartition.equations = eqs;
    (eqs, oa) = traverseExpsEqSystems(&subPartition.removedEquations, func.clone(), oa, metamodelica::nil())?;
    outSubPartition.removedEquations = eqs;
    Ok((outSubPartition, oa))
}

fn traverseExpsEqSystemsList<A: Clone + 'static + metamodelica::gc::MMTrace>(
    mut ieqs: metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>,
    mut func: Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >,
    mut ia: A,
    mut acc: metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>,
) -> Result<(
    metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>,
    A,
)> {
    pub type Func<A: Clone + 'static> = std::sync::Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >;

    let mut oeqs: metamodelica::List<metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>>;
    let mut oa: A;
    (oeqs, oa) = (::match_deref::match_deref! { match &(ieqs) {
        Deref @ metamodelica::ListNode::Nil => {
            let mut a = ia;
            (acc.reverse(), a)
        },
        Deref @ metamodelica::ListNode::Cons { head: eq, tail: eqs } => {
            let mut a = ia;
            let mut eq = (*eq).clone();
            (eq, a) = traverseExpsEqSystems(metamodelica::AsArg::as_arg(&eq), func.clone(), a, metamodelica::nil())?;
            (oeqs, a) = traverseExpsEqSystemsList(eqs.clone(), func.clone(), a, metamodelica::cons(eq.clone(), acc))?;
            (oeqs, a)
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok((oeqs, oa))
}

fn traverseExpsEqSystems<A: Clone + 'static + metamodelica::gc::MMTrace>(
    mut ieqs: &metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>,
    mut func: Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >,
    mut ia: A,
    mut acc: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>,
) -> Result<(metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>, A)> {
    pub type Func<A: Clone + 'static> = std::sync::Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >;

    let mut oeqs: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>;
    let mut oa: A = ia;
    let mut teq: metamodelica::Ref<SimCode::SimEqSystem>;
    let mut racc: metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>> = acc;
    for mut eq in &**ieqs {
        (teq, oa) = traverseExpsEqSystem(eq.clone(), func.clone(), oa)?;
        racc = metamodelica::cons(teq, racc);
    }
    oeqs = racc.reverse();
    Ok((oeqs, oa))
}

fn traverseStmtExp<A: Clone + 'static + metamodelica::gc::MMTrace>(
    mut inExp: metamodelica::Ref<DAE::Exp>,
    mut inStmt: &metamodelica::Ref<DAE::Statement>,
    mut inArg: A,
    mut func: &dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)>,
) -> Result<(metamodelica::Ref<DAE::Exp>, A)> {
    pub type Func<A: Clone + 'static> = std::sync::Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >;

    let mut outExp: metamodelica::Ref<DAE::Exp>;
    let mut outArg: A;
    (outExp, outArg) = func(inExp, inArg)?;
    Ok((outExp, outArg))
}

fn traverseExpsEqSystem<A: Clone + 'static + metamodelica::gc::MMTrace>(
    mut eq: metamodelica::Ref<SimCode::SimEqSystem>,
    mut func: Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >,
    mut ia: A,
) -> Result<(metamodelica::Ref<SimCode::SimEqSystem>, A)> {
    pub type Func<A: Clone + 'static> = std::sync::Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, A) -> Result<(metamodelica::Ref<DAE::Exp>, A)> + 'static,
    >;

    let mut oeq: metamodelica::Ref<SimCode::SimEqSystem>;
    let mut oa: A;
    (oeq, oa) = (match &*eq.clone() {
        SimCode::SimEqSystem::SES_RESIDUAL {
            index,
            res_index,
            exp,
            source,
            eqAttr,
        } => {
            let mut a = ia;
            let mut exp_: metamodelica::Ref<DAE::Exp>;
            let mut eq_: metamodelica::Ref<SimCode::SimEqSystem>;
            (exp_, a) = func(exp.clone(), a)?;
            if referenceEq(&*(exp.clone()), &*(&*exp_)) {
                eq_ = eq;
            } else {
                eq_ = metamodelica::Ref::new(SimCode::SimEqSystem::SES_RESIDUAL {
                    index: index.clone(),
                    res_index: res_index.clone(),
                    exp: exp_,
                    source: source.clone(),
                    eqAttr: eqAttr.clone(),
                });
            }
            (eq_, a)
        }
        SimCode::SimEqSystem::SES_FOR_RESIDUAL {
            index,
            res_index,
            iterators: _,
            exp,
            source,
            eqAttr,
        } => {
            let mut a = ia;
            let mut exp_: metamodelica::Ref<DAE::Exp>;
            let mut eq_: metamodelica::Ref<SimCode::SimEqSystem>;
            (exp_, a) = func(exp.clone(), a)?;
            if referenceEq(&*(exp.clone()), &*(&*exp_)) {
                eq_ = eq;
            } else {
                eq_ = metamodelica::Ref::new(SimCode::SimEqSystem::SES_FOR_RESIDUAL {
                    index: index.clone(),
                    res_index: res_index.clone(),
                    iterators: var_field!((*eq).iterators, SimCode::SimEqSystem::SES_FOR_RESIDUAL).clone(),
                    exp: exp_,
                    source: source.clone(),
                    eqAttr: eqAttr.clone(),
                });
            }
            (eq_, a)
        }
        SimCode::SimEqSystem::SES_GENERIC_RESIDUAL {
            index,
            res_index,
            scal_indices: _,
            iterators: _,
            exp,
            source,
            eqAttr,
        } => {
            let mut a = ia;
            let mut exp_: metamodelica::Ref<DAE::Exp>;
            let mut eq_: metamodelica::Ref<SimCode::SimEqSystem>;
            (exp_, a) = func(exp.clone(), a)?;
            if referenceEq(&*(exp.clone()), &*(&*exp_)) {
                eq_ = eq;
            } else {
                eq_ = metamodelica::Ref::new(SimCode::SimEqSystem::SES_GENERIC_RESIDUAL {
                    index: index.clone(),
                    res_index: res_index.clone(),
                    scal_indices: var_field!((*eq).scal_indices, SimCode::SimEqSystem::SES_GENERIC_RESIDUAL).clone(),
                    iterators: var_field!((*eq).iterators, SimCode::SimEqSystem::SES_GENERIC_RESIDUAL).clone(),
                    exp: exp_,
                    source: source.clone(),
                    eqAttr: eqAttr.clone(),
                });
            }
            (eq_, a)
        }
        SimCode::SimEqSystem::SES_SIMPLE_ASSIGN {
            index,
            cref: cr,
            exp,
            source,
            eqAttr,
        } => {
            let mut a = ia;
            let mut exp_: metamodelica::Ref<DAE::Exp>;
            let mut eq_: metamodelica::Ref<SimCode::SimEqSystem>;
            (exp_, a) = func(exp.clone(), a)?;
            if referenceEq(&*(exp.clone()), &*(&*exp_)) {
                eq_ = eq;
            } else {
                eq_ = metamodelica::Ref::new(SimCode::SimEqSystem::SES_SIMPLE_ASSIGN {
                    index: index.clone(),
                    cref: cr.clone(),
                    exp: exp_,
                    source: source.clone(),
                    eqAttr: eqAttr.clone(),
                });
            }
            (eq_, a)
        }
        SimCode::SimEqSystem::SES_SIMPLE_ASSIGN_CONSTRAINTS {
            index,
            cref: cr,
            exp,
            source,
            cons,
            eqAttr,
        } => {
            let mut a = ia;
            let mut exp_: metamodelica::Ref<DAE::Exp>;
            let mut eq_: metamodelica::Ref<SimCode::SimEqSystem>;
            (exp_, a) = func(exp.clone(), a)?;
            if referenceEq(&*(exp.clone()), &*(&*exp_)) {
                eq_ = eq;
            } else {
                eq_ = metamodelica::Ref::new(SimCode::SimEqSystem::SES_SIMPLE_ASSIGN_CONSTRAINTS {
                    index: index.clone(),
                    cref: cr.clone(),
                    exp: exp_,
                    source: source.clone(),
                    cons: cons.clone(),
                    eqAttr: eqAttr.clone(),
                });
            }
            (eq_, a)
        }
        SimCode::SimEqSystem::SES_ARRAY_CALL_ASSIGN {
            index,
            lhs: leftexp,
            exp,
            source,
            eqAttr,
        } => {
            let mut a = ia;
            let mut leftexp = (*leftexp).clone();
            let mut exp = (*exp).clone();
            (leftexp, a) = func(leftexp.clone(), a)?;
            (exp, a) = func(exp.clone(), a)?;
            (
                metamodelica::Ref::new(SimCode::SimEqSystem::SES_ARRAY_CALL_ASSIGN {
                    index: index.clone(),
                    lhs: leftexp.clone(),
                    exp: exp.clone(),
                    source: source.clone(),
                    eqAttr: eqAttr.clone(),
                }),
                a,
            )
        }
        SimCode::SimEqSystem::SES_IFEQUATION { .. } => {
            let mut a = ia;
            (eq, a)
        }
        SimCode::SimEqSystem::SES_ALGORITHM { .. } => {
            let mut a = ia;
            let mut eq_: metamodelica::Ref<SimCode::SimEqSystem>;
            let mut stmts: metamodelica::List<metamodelica::Ref<DAE::Statement>>;
            (stmts, a) = DAEUtil::traverseDAEStmts(
                var_field!((*eq).statements, SimCode::SimEqSystem::SES_ALGORITHM),
                &({
                    let __pe_b3: Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, _) -> Result<_> + 'static> =
                        func.clone();
                    move |__pe_a0, __pe_a1, __pe_a2| traverseStmtExp(__pe_a0, &__pe_a1, __pe_a2, &*__pe_b3)
                }),
                a,
            )?;
            eq_ = metamodelica::Ref::new(SimCode::SimEqSystem::SES_ALGORITHM {
                index: var_field!((*eq).index, SimCode::SimEqSystem::SES_ALGORITHM).clone(),
                statements: stmts,
                eqAttr: var_field!((*eq).eqAttr, SimCode::SimEqSystem::SES_ALGORITHM).clone(),
            });
            (eq_, a)
        }
        SimCode::SimEqSystem::SES_INVERSE_ALGORITHM { .. } => {
            let mut a = ia;
            let mut eq_: metamodelica::Ref<SimCode::SimEqSystem>;
            let mut stmts: metamodelica::List<metamodelica::Ref<DAE::Statement>>;
            (stmts, a) = DAEUtil::traverseDAEStmts(
                var_field!((*eq).statements, SimCode::SimEqSystem::SES_INVERSE_ALGORITHM),
                &({
                    let __pe_b3: Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, _) -> Result<_> + 'static> =
                        func.clone();
                    move |__pe_a0, __pe_a1, __pe_a2| traverseStmtExp(__pe_a0, &__pe_a1, __pe_a2, &*__pe_b3)
                }),
                a,
            )?;
            eq_ = metamodelica::Ref::new(SimCode::SimEqSystem::SES_INVERSE_ALGORITHM {
                index: var_field!((*eq).index, SimCode::SimEqSystem::SES_INVERSE_ALGORITHM).clone(),
                statements: stmts,
                knownOutputCrefs: var_field!((*eq).knownOutputCrefs, SimCode::SimEqSystem::SES_INVERSE_ALGORITHM)
                    .clone(),
                insideNonLinearSystem: var_field!(
                    (*eq).insideNonLinearSystem,
                    SimCode::SimEqSystem::SES_INVERSE_ALGORITHM
                )
                .clone(),
                eqAttr: var_field!((*eq).eqAttr, SimCode::SimEqSystem::SES_INVERSE_ALGORITHM).clone(),
            });
            (eq_, a)
        }
        SimCode::SimEqSystem::SES_LINEAR { .. } => {
            let mut a = ia;
            (eq, a)
        }
        SimCode::SimEqSystem::SES_NONLINEAR { .. } => {
            let mut a = ia;
            (eq, a)
        }
        SimCode::SimEqSystem::SES_MIXED { .. } => {
            let mut a = ia;
            (eq, a)
        }
        SimCode::SimEqSystem::SES_WHEN { .. } => {
            let mut a = ia;
            (eq, a)
        }
        SimCode::SimEqSystem::SES_FOR_LOOP { .. } => {
            let mut a = ia;
            (eq, a)
        }
        SimCode::SimEqSystem::SES_FOR_EQUATION { .. } => {
            let mut a = ia;
            (eq, a)
        }
        SimCode::SimEqSystem::SES_ALIAS { .. } => {
            let mut a = ia;
            (eq, a)
        }
        _ => {
            Error::addInternalError(
                {
                    let mut __mm_s = String::new();
                    __mm_s.push_str(&*literal!("SimCodeUtil.traverseExpsEqSystem"));
                    __mm_s.push_str(&*literal!(" got unknown equation"));
                    ArcStr::from(__mm_s)
                },
                metamodelica::sourceInfo!("SimCode/SimCodeUtil.mo"),
            )?;
            return Err("fail");
        }
    });
    Ok((oeq, oa))
}

fn setSimCodeLiterals(
    mut simCode: metamodelica::Ref<SimCode::SimCode>,
    mut literals: metamodelica::List<metamodelica::Ref<DAE::Exp>>,
) -> metamodelica::Ref<SimCode::SimCode> {
    let mut outSimCode: metamodelica::Ref<SimCode::SimCode> = simCode;
    assign_field!(outSimCode.literals = literals);
    outSimCode
}

fn eqSystemWCET(
    mut eqs: metamodelica::Ref<SimCode::SimEqSystem>,
) -> Result<(metamodelica::Ref<SimCode::SimEqSystem>, i32)> {
    let mut tpl: (metamodelica::Ref<SimCode::SimEqSystem>, i32);
    let mut i: i32;
    (_, i) = traverseExpsEqSystems(
        &(list![eqs.clone()]),
        (std::sync::Arc::new(Expression::complexityTraverse)
            as std::sync::Arc<
                dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, i32) -> Result<(metamodelica::Ref<DAE::Exp>, i32)>
                    + 'static,
            >),
        0,
        metamodelica::nil(),
    )?;
    tpl = (eqs, i);
    Ok(tpl)
}

fn getHideResult(
    mut hideResultExp: Option<metamodelica::Ref<DAE::Exp>>,
    mut name: &metamodelica::Ref<DAE::ComponentRef>,
    mut source: metamodelica::Ref<DAE::ElementSource>,
) -> Result<Option<bool>> {
    let mut hideResult: Option<bool>;
    hideResult = (::match_deref::match_deref! { match &(hideResultExp) {
        None => None,
        Some(Deref @ DAE::Exp::BCONST { bool: false }) => Some(false),
        Some(Deref @ DAE::Exp::BCONST { bool: true }) => Some(true),
        _ => {
            Error::addSourceMessage(&(Error::HIDE_RESULT_NOT_EVALUATED.clone()), list![ComponentReferenceBasics::printComponentRefStr(name)?], &(ElementSource::getInfo(source)))?;
            None
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(hideResult)
}

