pub(crate) fn getAssignedCrefsOfSimEq(
    mut idx: i32,
    mut simCode: &metamodelica::Ref<SimCode::SimCode>,
) -> Result<metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>> {
    let mut crefsOut: metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>;
    crefsOut = (match &**simCode {
        SimCode::SimCode {
            allEquations: allEqs, ..
        } => {
            let mut simEqSyst: metamodelica::Ref<SimCode::SimEqSystem>;
            let mut crefs: metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>;
            simEqSyst = List::getMemberOnTrue(
                idx,
                allEqs,
                &move |__a0: i32, __a1: metamodelica::Ref<SimCode::SimEqSystem>| {
                    SimCodeCodegenUtil::indexIsEqual(__a0, &__a1)
                },
            )?;
            crefs = SimCodeCodegenUtil::getSimEqSystemCrefsLHS(&simEqSyst)?;
            crefs
        }
    });
    Ok(crefsOut)
}

