fn dumpBackendMapping(mut mapIn: SimCode::BackendMapping) -> Result<()> {
    let mut eqMatch: metamodelica::Array<i32>;
    let mut varMatch: metamodelica::Array<i32>;
    let mut tree: metamodelica::Array<metamodelica::List<i32>>;
    let mut eqMapping: metamodelica::List<(i32, metamodelica::List<i32>)>;
    let mut varMapping: metamodelica::List<(i32, i32)>;
    let mut m: metamodelica::Array<metamodelica::List<i32>>;
    let mut mt: metamodelica::Array<metamodelica::List<i32>>;
    let mut simVarMapping: metamodelica::Array<metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>>;
    let SimCode::BACKENDMAPPING {
        m: __pa0,
        mT: __pa1,
        eqMapping: __pa2,
        varMapping: __pa3,
        eqMatch: __pa4,
        varMatch: __pa5,
        eqTree: __pa6,
        simVarMapping: __pa7,
    } = (mapIn)
    else {
        return Err("pattern mismatch");
    };
    m = metamodelica::Own::own(__pa0);
    mt = metamodelica::Own::own(__pa1);
    eqMapping = metamodelica::Own::own(__pa2);
    varMapping = metamodelica::Own::own(__pa3);
    eqMatch = metamodelica::Own::own(__pa4);
    varMatch = metamodelica::Own::own(__pa5);
    tree = metamodelica::Own::own(__pa6);
    simVarMapping = metamodelica::Own::own(__pa7);
    dumpEqMapping(eqMapping)?;
    Ok(())
}

