fn fmiUnknownsOf(
    mut vars: &metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
    mut unknowns: metamodelica::List<SimCode::FmiUnknown>,
) -> Result<metamodelica::List<SimCode::FmiUnknown>> {
    let mut selected: metamodelica::List<SimCode::FmiUnknown>;
    let mut indices: metamodelica::Ref<UnorderedSet::UnorderedSet<i32>> = UnorderedSet::new(
        std::sync::Arc::new(fnptr!(Util::id, _)),
        (std::sync::Arc::new(fnptr!(intEq, i32, i32))
            as std::sync::Arc<dyn ::std::ops::Fn(i32, i32) -> Result<bool> + 'static>),
        Util::nextPrime(((vars).len() as i32)),
    );
    for mut v in &**vars {
        UnorderedSet::add(
            SimCodeCodegenUtil::getVariableFMIIndex(metamodelica::AsArg::as_arg(&v)),
            indices.clone(),
        )?;
    }
    selected = ({
        let mut __acc: metamodelica::List<SimCode::FmiUnknown> = metamodelica::nil();
        for mut u in (unknowns).into_iter().cloned() {
            if !(UnorderedSet::contains(u.index.clone(), indices.clone())?) {
                continue;
            }
            let __x = u.clone();
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    });
    Ok(selected)
}

fn translateSparsePatterInts2FMIUnknown<'__b>(
    mut inSparsePattern: &'__b metamodelica::List<(i32, metamodelica::List<i32>)>,
    mut inAccum: metamodelica::List<SimCode::FmiUnknown>,
) -> metamodelica::List<SimCode::FmiUnknown> {
    '__tco: loop {
        ::match_deref::match_deref! { match inSparsePattern {
            Deref @ metamodelica::ListNode::Nil => {
                return inAccum.reverse()
            },
            Deref @ metamodelica::ListNode::Cons { head: (unknown, dependencies), tail: rest } => {
                let mut dependenciesKind: metamodelica::List<ArcStr>;
                dependenciesKind = List::fill(literal!("dependent"), ((dependencies).len() as i32));
                { (inSparsePattern, inAccum) = (rest, metamodelica::cons(SimCode::FmiUnknown { index: unknown.clone(), dependencies: dependencies.clone(), dependenciesKind: dependenciesKind }, inAccum)); continue '__tco; }
            },
            _ => unreachable!("tail-call lowered match: no arm matched"),
        } }
    }
}

fn translateSparsePatterCref2DerCref<'__b>(
    mut sparsePattern: &'__b metamodelica::List<(
        metamodelica::Ref<DAE::ComponentRef>,
        metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
    )>,
    mut inSimVarHT: &'__b (
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::ComponentRef>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<
                Option<(
                    metamodelica::Ref<DAE::ComponentRef>,
                    metamodelica::Ref<SimCodeVar::SimVar>,
                )>,
            >,
        ),
        i32,
        (
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::ComponentRef>) -> Result<i32> + 'static>,
            Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<DAE::ComponentRef>,
                        metamodelica::Ref<DAE::ComponentRef>,
                    ) -> Result<bool>
                    + 'static,
            >,
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::ComponentRef>) -> Result<ArcStr> + 'static>,
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<SimCodeVar::SimVar>) -> Result<ArcStr> + 'static>,
        ),
    ),
    mut inAccum: metamodelica::List<(
        metamodelica::Ref<DAE::ComponentRef>,
        metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
    )>,
    mut inAccum2: metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
) -> Result<(
    metamodelica::List<(
        metamodelica::Ref<DAE::ComponentRef>,
        metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
    )>,
    metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
)> {
    '__tco: loop {
        ::match_deref::match_deref! { match sparsePattern {
            Deref @ metamodelica::ListNode::Nil => {
                return Ok((inAccum.reverse(), inAccum2.reverse()))
            },
            Deref @ metamodelica::ListNode::Cons { head: (cref, crefs), tail: rest } => {
                let mut simVar: metamodelica::Ref<SimCodeVar::SimVar>;
                let mut cref = (*cref).clone();
                simVar = BaseHashTable::get(cref.clone(), inSimVarHT)?;
                if BackendVariable::isVarKindState(&simVar.varKind) {
                    cref = ComponentReference::crefPrefixDer(cref.clone());
                }
                { (sparsePattern, inSimVarHT, inAccum, inAccum2) = (rest, inSimVarHT, metamodelica::cons((cref.clone(), crefs.clone()), inAccum), metamodelica::cons(cref.clone(), inAccum2)); continue '__tco; }
            },
            _ => return Err("match: no arm matched"),
        } }
    }
}

fn mergeSparsePatter<'__b>(
    mut inA: &'__b metamodelica::List<(
        metamodelica::Ref<DAE::ComponentRef>,
        metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
    )>,
    mut inB: &'__b metamodelica::List<(
        metamodelica::Ref<DAE::ComponentRef>,
        metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
    )>,
    mut inAccum: metamodelica::List<(
        metamodelica::Ref<DAE::ComponentRef>,
        metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
    )>,
) -> Result<
    metamodelica::List<(
        metamodelica::Ref<DAE::ComponentRef>,
        metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>,
    )>,
> {
    '__tco: loop {
        ::match_deref::match_deref! { match (inA, inB) {
            (Deref @ metamodelica::ListNode::Nil, Deref @ metamodelica::ListNode::Nil) => {
                return Ok(inAccum.reverse())
            },
            (Deref @ metamodelica::ListNode::Nil, _) => {
                return Ok(inB.clone())
            },
            (_, Deref @ metamodelica::ListNode::Nil) => {
                return Ok(inA.clone())
            },
            (Deref @ metamodelica::ListNode::Cons { head: (crefA, listA), tail: restA }, Deref @ metamodelica::ListNode::Cons { head: (crefB, listB), tail: restB }) => {
                let mut listOut: metamodelica::List<metamodelica::Ref<DAE::ComponentRef>>;
                let true = (ComponentReferenceBasics::crefEqual(metamodelica::AsArg::as_arg(&crefA), metamodelica::AsArg::as_arg(&crefB))?) else { return Err("pattern mismatch") };
                listOut = List::unionOnTrue(metamodelica::AsArg::as_arg(&listA), metamodelica::AsArg::as_arg(&listB), &move |__a0: metamodelica::Ref<DAE::ComponentRef>, __a1: metamodelica::Ref<DAE::ComponentRef>| ComponentReferenceBasics::crefEqual(&__a0, &__a1))?;
                { (inA, inB, inAccum) = (restA, restB, metamodelica::cons((crefA.clone(), listOut), inAccum)); continue '__tco; }
            },
            _ => return Err("match: no arm matched"),
        } }
    }
}

fn getScalarVars(
    mut inVars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
) -> Result<metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>> {
    let mut outVars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>;
    outVars = metamodelica::nil();
    for mut var in &*inVars.reverse() {
        outVars = listAppend(SimCodeCodegenUtil::getScalarElements(var.clone())?, outVars);
    }
    Ok(outVars)
}

pub fn exportDaeAlgebraicStates(
    mut modelInfo: SimCode::ModelInfo,
    mut algebraicStateVars: &metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
) -> Result<SimCode::ModelInfo> {
    let mut modelInfo: SimCode::ModelInfo = modelInfo;
    let mut crefs: (
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::ComponentRef>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<Option<metamodelica::Ref<DAE::ComponentRef>>>,
        ),
        i32,
        i32,
        (HashSet::FuncHashCref, HashSet::FuncCrefEqual, HashSet::FuncCrefStr),
    ) = HashSet::emptyHashSet();
    let mut vars: SimCodeVar::SimVars;
    for mut v in &**algebraicStateVars {
        crefs = BaseHashSet::add(v.name.clone(), &crefs)?;
    }
    vars = modelInfo.vars.clone();
    vars.algVars = ({
        let mut __acc: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>> = metamodelica::nil();
        for mut v in (vars.algVars.clone()).into_iter().cloned() {
            let __x = exportIfAlgebraicState(v.clone(), &crefs)?;
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    });
    modelInfo.vars = vars;
    Ok(modelInfo)
}

fn exportIfAlgebraicState(
    mut v: metamodelica::Ref<SimCodeVar::SimVar>,
    mut crefs: &(
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<DAE::ComponentRef>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<Option<metamodelica::Ref<DAE::ComponentRef>>>,
        ),
        i32,
        i32,
        (
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::ComponentRef>) -> Result<i32> + 'static>,
            Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<DAE::ComponentRef>,
                        metamodelica::Ref<DAE::ComponentRef>,
                    ) -> Result<bool>
                    + 'static,
            >,
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::ComponentRef>) -> Result<ArcStr> + 'static>,
        ),
    ),
) -> Result<metamodelica::Ref<SimCodeVar::SimVar>> {
    let mut v: metamodelica::Ref<SimCodeVar::SimVar> = v;
    if (v.exportVar).is_none() && BaseHashSet::has(v.name.clone(), crefs)? {
        assign_field!(
            v.exportVar = Some(
                if (Flags::getConfigEnum(Flags::FMI_FILTER.clone())? == Flags::FMI_BLACKBOX.clone()) {
                    ComponentReference::getConcealedCref()
                } else {
                    v.name.clone()
                }
            )
        );
    }
    Ok(v)
}

pub const FMI_LS_DAE_DRAFT_DATE: &'static str = "2026-09-02";

