fn getHighestDerivation(mut inDAE: &metamodelica::Ref<BackendDAE::BackendDAE>) -> Result<i32> {
    let mut highestDerivation: i32;
    let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
    let mut states: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
    let mut ders: metamodelica::Array<i32>;
    let mut depth: metamodelica::Array<i32>;
    let mut allStates: BackendDAE::Variables;
    let mut var: metamodelica::Ref<BackendDAE::Var> =
        <metamodelica::Ref<BackendDAE::Var> as ::std::default::Default>::default();
    let mut index: i32;
    let mut pos: i32 = 0;
    let mut length: i32;
    let mut curIndex: i32;
    let mut derCref: metamodelica::Ref<DAE::ComponentRef>;
    vars = BackendDAEUtil::getAllVarLst(inDAE)?;
    states = List::filterOnTrue(
        vars,
        (std::sync::Arc::new(
            move |__a0: metamodelica::Ref<BackendDAE::Var>| -> metamodelica::Result<_> {
                ::std::result::Result::Ok(BackendVariable::isStateVar(&__a0))
            },
        ) as std::sync::Arc<dyn ::std::ops::Fn(metamodelica::Ref<BackendDAE::Var>) -> Result<bool> + 'static>),
    )?;
    length = ((states).len() as i32);
    if length == 0 {
        highestDerivation = 0;
        return Ok(highestDerivation);
    }
    ders = arrayCreate(length, -1);
    depth = arrayCreate(length, -1);
    allStates = BackendVariable::listVar1(&states)?;
    curIndex = 1;
    for mut state in &*states {
        let () = 'mc: {
            let __mc_input = state.clone();
            if let Ok((__v, __wb0, __wb1)) = (|| -> Result<_> {
                ::match_deref::match_deref! { match &__mc_input {
                    Deref @ BackendDAE::Var { varKind: BackendDAE::VarKind::STATE { index, derName: Some(derCref), .. }, .. } => {
                        let mut pos: i32 = pos.clone();
                        let mut var: metamodelica::Ref<BackendDAE::Var> = var.clone();
                        (var, pos) = BackendVariable::getVarSingle(metamodelica::AsArg::as_arg(&derCref), &allStates)?;
                        if !(BackendVariable::varEqual(metamodelica::AsArg::as_arg(&state), &var)?) {
                            metamodelica::arrayUpdate(ders.clone(), curIndex, pos)?;
                        } else {
                            metamodelica::arrayUpdate(depth.clone(), curIndex, 0)?;
                        }
                        Ok(((), pos.clone(), var.clone()))
                    }
                    _ => return Err("nomatch"),
                }}
            })() {
                pos = __wb0;
                var = __wb1;
                break 'mc __v;
            }
            if let Ok(__v) = (|| -> Result<_> {
                ::match_deref::match_deref! { match &__mc_input {
                    Deref @ BackendDAE::Var { .. } => {
                        metamodelica::arrayUpdate(depth.clone(), curIndex, 0)?;
                        Ok(())
                    }
                    _ => return Err("nomatch"),
                }}
            })() {
                break 'mc __v;
            }
            return Err("matchcontinue: no arm matched");
        };
        curIndex = curIndex + 1;
    }
    for mut i in 1..=length {
        getHighestDerivationVisit(i, ders.clone(), depth.clone())?;
    }
    highestDerivation = ({
        let mut __acc: Option<i32> = None;
        for mut i in (depth.clone()).borrow().iter() {
            let __x = i.clone();
            __acc = Some(match __acc {
                None => __x,
                Some(__cur) => {
                    if __x > __cur {
                        __x
                    } else {
                        __cur
                    }
                }
            });
        }
        __acc.unwrap_or((-i32::MAX))
    });
    GCExt::free(ders.clone());
    GCExt::free(depth.clone());
    Ok(highestDerivation)
}

fn getHighestDerivationVisit(
    mut i: i32,
    mut ders: metamodelica::Array<i32>,
    mut depth: metamodelica::Array<i32>,
) -> Result<i32> {
    let mut d: i32 = metamodelica::arrayGet(depth.clone(), i)?;
    if d >= 0 {
        return Ok(d);
    } else if d == -2 {
        d = 0;
        return Ok(d);
    }
    metamodelica::arrayUpdate(depth.clone(), i, -2)?;
    d = getHighestDerivationVisit(metamodelica::arrayGet(ders.clone(), i)?, ders.clone(), depth.clone())?;
    metamodelica::arrayUpdate(depth.clone(), i, d)?;
    Ok(d)
}

fn hasLargeEquationSystems(
    mut iDlow: &metamodelica::Ref<BackendDAE::BackendDAE>,
    mut iInitDAE: &metamodelica::Ref<BackendDAE::BackendDAE>,
) -> Result<bool> {
    let mut oHasLargeEqSystem: bool;
    let mut hasLargeEqSystem: bool = false;
    let mut eqs: metamodelica::List<metamodelica::Ref<BackendDAE::EqSystem>> = metamodelica::nil();
    let __arc1 = &(*iDlow);
    let BackendDAE::DAE { eqs: __pa0, .. } = &**__arc1;
    eqs = metamodelica::Own::own(__pa0);
    for mut eqsys in &*eqs {
        if boolNot(hasLargeEqSystem) {
            hasLargeEqSystem =
                hasLargeEquationSystems1(&(BackendDAEUtil::getStrongComponents(metamodelica::AsArg::as_arg(&eqsys))))?;
        }
    }
    if boolNot(hasLargeEqSystem) {
        let __arc3 = &(*iInitDAE);
        let BackendDAE::DAE { eqs: __pa2, .. } = &**__arc3;
        eqs = metamodelica::Own::own(__pa2);
        for mut eqsys in &*eqs {
            if boolNot(hasLargeEqSystem) {
                hasLargeEqSystem = hasLargeEquationSystems1(
                    &(BackendDAEUtil::getStrongComponents(metamodelica::AsArg::as_arg(&eqsys))),
                )?;
            }
        }
    }
    if Flags::isSet(Flags::DUMP_DGESV.clone())? {
        if boolNot(hasLargeEqSystem) {
            metamodelica::print(literal!(
                "This model has no large linear or nonlinear equation system, thus the use of dgesv (OMCompiler/3rdParty/) is prefered.\n"
            ));
        } else {
            metamodelica::print(literal!(
                "This model has at least one large or nonlinear linear equation system, thus the use of Lapack is prefered.\n"
            ));
        }
    }
    oHasLargeEqSystem = hasLargeEqSystem;
    Ok(oHasLargeEqSystem)
}

fn hasLargeEquationSystems1(
    mut iComps: &metamodelica::List<metamodelica::Ref<BackendDAE::StrongComponent>>,
) -> Result<bool> {
    let mut oHasLargeEquationSystems: bool;
    let mut hasLargeEqSystem: bool = false;
    let mut vars: metamodelica::List<i32>;
    for mut comp in &**iComps {
        if boolNot(hasLargeEqSystem) {
            if boolOr(
                BackendDAEUtil::isLinearEqSystemComp(metamodelica::AsArg::as_arg(&comp)),
                BackendDAEUtil::isNonLinearEqSystemComp(metamodelica::AsArg::as_arg(&comp)),
            ) {
                let __pa0 = ::match_deref::match_deref! { match &(comp.clone()) {
                    Deref @ BackendDAE::StrongComponent::EQUATIONSYSTEM { vars: __pa0, .. } => __pa0.clone(),
                    _ => return Err("pattern mismatch"),
                } };
                vars = metamodelica::Own::own(__pa0);
                hasLargeEqSystem = intGt(((vars).len() as i32), 10);
            } else {
                if boolOr(
                    BackendDAEUtil::isLinearTornSystemComp(metamodelica::AsArg::as_arg(&comp)),
                    BackendDAEUtil::isNonLinearTornSystemComp(metamodelica::AsArg::as_arg(&comp)),
                ) {
                    let __pa1 = ::match_deref::match_deref! { match &(comp.clone()) {
                        Deref @ BackendDAE::StrongComponent::TORNSYSTEM { strictTearingSet: BackendDAE::TearingSet { tearingvars: __pa1, .. }, .. } => __pa1.clone(),
                        _ => return Err("pattern mismatch"),
                    } };
                    vars = metamodelica::Own::own(__pa1);
                    hasLargeEqSystem = intGt(((vars).len() as i32), 10);
                }
            }
        }
    }
    oHasLargeEquationSystems = hasLargeEqSystem;
    Ok(oHasLargeEquationSystems)
}

fn createSimVarsForSensitivities(
    mut inStateSimVars: &metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
    mut inParamSimVars: &metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
    mut nFixedParameters: i32,
) -> Result<(metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>, i32)> {
    let mut outSimCodeVars: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>;
    let mut countSensitivityParams: i32 = 0;
    let debug: bool = false;
    let mut tmpVariables: BackendDAE::Variables;
    let mut emptyVars: BackendDAE::Variables;
    let mut var: metamodelica::Ref<BackendDAE::Var>;
    let mut cref: metamodelica::Ref<DAE::ComponentRef>;
    let mut sensitivityParams: metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>> = metamodelica::nil();
    emptyVars = BackendVariable::emptyVars(BaseHashTable::bigBucketSize.clone());
    tmpVariables = BackendVariable::emptyVarsSized(((inStateSimVars).len() as i32) * nFixedParameters);
    for mut param in &**inParamSimVars {
        if param.isValueChangeable.clone() && ComponentReference::crefIsIdent(&param.name) {
            countSensitivityParams = countSensitivityParams + 1;
            sensitivityParams = metamodelica::cons(param.clone(), sensitivityParams);
            for mut state in &**inStateSimVars {
                cref = ComponentReferenceBasics::makeCrefIdent(
                    literal!("$Sensitivities"),
                    DAE::T_REAL_DEFAULT().clone(),
                    metamodelica::nil(),
                );
                cref = ComponentReference::joinCrefs(&cref, param.name.clone())?;
                cref = ComponentReference::joinCrefs(&cref, state.name.clone())?;
                if debug {
                    metamodelica::print({
                        let mut __mm_s = String::new();
                        __mm_s.push_str(&*literal!("createSimVarsForSensitivities for Var: "));
                        __mm_s.push_str(&*ComponentReference::crefStr(&cref)?);
                        __mm_s.push_str(&*literal!("\n"));
                        ArcStr::from(__mm_s)
                    });
                }
                var = BackendVariable::makeVar(cref)?;
                tmpVariables = BackendVariable::addNewVar(var, tmpVariables)?;
            }
        }
    }
    (outSimCodeVars, _) = BackendVariable::traverseBackendDAEVars(
        tmpVariables,
        (std::sync::Arc::new(
            move |__a0: metamodelica::Ref<BackendDAE::Var>,
                  __a1: (
                metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
                BackendDAE::Variables,
            )| traversingdlowvarToSimvar(__a0, &__a1),
        )
            as std::sync::Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<BackendDAE::Var>,
                        (
                            metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
                            BackendDAE::Variables,
                        ),
                    ) -> Result<(
                        metamodelica::Ref<BackendDAE::Var>,
                        (
                            metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
                            BackendDAE::Variables,
                        ),
                    )> + 'static,
            >),
        (metamodelica::nil(), emptyVars),
    )?;
    outSimCodeVars = outSimCodeVars.reverse();
    outSimCodeVars = listAppend(sensitivityParams.reverse(), outSimCodeVars);
    Ok((outSimCodeVars, countSensitivityParams))
}

