fn figureBoundArg(
    mut args: &metamodelica::List<(ArcStr, metamodelica::Ref<Absyn::Exp>)>,
    mut name: &ArcStr,
) -> Result<Option<metamodelica::Real>> {
    let mut value: Option<metamodelica::Real>;
    value = (::match_deref::match_deref! { match &(figureArgExp(args, name)) {
        Some(e) => {
            Some(figureExpReal(metamodelica::AsArg::as_arg(&e))?)
        },
        _ => {
            None
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(value)
}

fn figureExpReal(mut exp: &metamodelica::Ref<Absyn::Exp>) -> Result<metamodelica::Real> {
    let mut value: metamodelica::Real;
    value = (match &**exp {
        Absyn::Exp::INTEGER { value: i } => intReal(i.clone()),
        Absyn::Exp::REAL { value: s } => stringReal(s.clone())?,
        Absyn::Exp::UNARY {
            op: Absyn::Operator::UMINUS { .. },
            exp: __exp_exp,
        } => -(figureExpReal(metamodelica::AsArg::as_arg(&__exp_exp))?),
        _ => metamodelica::OrderedFloat(0.0_f64),
    });
    Ok(value)
}

fn figureScaleIsLog(mut oexp: Option<metamodelica::Ref<Absyn::Exp>>) -> Result<bool> {
    let mut isLog: bool;
    isLog = (::match_deref::match_deref! { match &(oexp) {
        Some(Deref @ Absyn::Exp::CALL { function_: cr, .. }) => {
            stringEq(&(AbsynUtil::crefIdent(metamodelica::AsArg::as_arg(&cr))?), &(literal!("Log")))
        },
        Some(Deref @ Absyn::Exp::CREF { componentRef: cr }) => {
            stringEq(&(AbsynUtil::crefIdent(metamodelica::AsArg::as_arg(&cr))?), &(literal!("Log")))
        },
        _ => {
            false
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(isLog)
}

fn getValueReferenceMapping2(
    mut vars: &metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
    mut i: i32,
    mut tree: metamodelica::Ref<AvlTreeCRToInt::Tree>,
) -> Result<(i32, metamodelica::Ref<AvlTreeCRToInt::Tree>)> {
    let mut i: i32 = i;
    let mut tree: metamodelica::Ref<AvlTreeCRToInt::Tree> = tree;
    for mut v in &**vars {
        tree = AvlTreeCRToInt::add(
            tree,
            &v.name,
            i,
            &*(std::sync::Arc::new(AvlTreeCRToInt::addConflictDefault)
                as std::sync::Arc<dyn ::std::ops::Fn(_, _, _) -> Result<_> + 'static>),
        )?;
        i = i + SimCodeUtilShared::getNumElems(metamodelica::AsArg::as_arg(&v))?;
    }
    Ok((i, tree))
}

fn getResources(
    mut classes: &metamodelica::List<metamodelica::Ref<Absyn::Class>>,
    mut dlow1: &metamodelica::Ref<BackendDAE::BackendDAE>,
    mut dlow2: &metamodelica::Ref<BackendDAE::BackendDAE>,
) -> Result<metamodelica::List<ArcStr>> {
    type Func = std::sync::Arc<
        dyn ::std::ops::Fn(
                metamodelica::Ref<DAE::Exp>,
                metamodelica::Ref<AvlSetString::Tree>,
            ) -> Result<(metamodelica::Ref<DAE::Exp>, metamodelica::Ref<AvlSetString::Tree>)>
            + 'static,
    >;

    let mut resources: metamodelica::List<ArcStr>;
    let mut tree: metamodelica::Ref<AvlSetString::Tree>;
    let mut fns: metamodelica::List<DAE::Function>;
    let mut unknownUri: Mutable::Mutable<bool>;
    let mut f1: Arc<
        dyn ::std::ops::Fn(
                metamodelica::Ref<DAE::Exp>,
                metamodelica::Ref<AvlSetString::Tree>,
            ) -> Result<(metamodelica::Ref<DAE::Exp>, metamodelica::Ref<AvlSetString::Tree>)>
            + 'static,
    >;
    let mut f2: Arc<
        dyn ::std::ops::Fn(
                metamodelica::Ref<DAE::Exp>,
                metamodelica::Ref<AvlSetString::Tree>,
            ) -> Result<(metamodelica::Ref<DAE::Exp>, metamodelica::Ref<AvlSetString::Tree>)>
            + 'static,
    >;
    let mut file: ArcStr;
    fns = DAEUtil::getFunctionList(&dlow1.shared.functionTree, false)?;
    tree = openmodelica_util::AvlSetString::Tree::interned_EMPTY();
    unknownUri = Mutable::create(false);
    f1 = (std::sync::Arc::new({
        let __pe_b2 = unknownUri.clone();
        move |__pe_a0, __pe_a1| findResources(__pe_a0, __pe_a1, __pe_b2.clone())
    })
        as std::sync::Arc<
            dyn ::std::ops::Fn(
                    metamodelica::Ref<DAE::Exp>,
                    metamodelica::Ref<AvlSetString::Tree>,
                )
                    -> Result<(metamodelica::Ref<DAE::Exp>, metamodelica::Ref<AvlSetString::Tree>)>
                + 'static,
        >);
    f2 = (std::sync::Arc::new({
        let __pe_b2: Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, _) -> Result<_> + 'static> = f1.clone();
        move |__pe_a0, __pe_a1| Expression::traverseSubexpressions(__pe_a0, __pe_a1, &*__pe_b2)
    }) as std::sync::Arc<dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, _) -> Result<_> + 'static>);
    (_, tree) = DAEUtil::traverseDAEFunctions(fns, f2.clone(), tree)?;
    tree = BackendDAEUtil::traverseBackendDAEExpsNoCopyWithUpdate(dlow1, f2.clone(), tree)?;
    tree = BackendDAEUtil::traverseBackendDAEExpsNoCopyWithUpdate(dlow2, f2.clone(), tree)?;
    resources = AvlSetString::listKeys(&tree, metamodelica::nil());
    if Mutable::access(unknownUri) {
        for mut cl in &**classes {
            file = cl.info.fileName.clone();
            if metamodelica::stringEq(&(System::basename(file.clone())), &(literal!("package.mo"))) {
                resources = metamodelica::cons(System::dirname(file), resources);
            }
        }
    }
    Ok(resources)
}

fn findResources(
    mut e: metamodelica::Ref<DAE::Exp>,
    mut tree: metamodelica::Ref<AvlSetString::Tree>,
    mut unknownUri: Mutable::Mutable<bool>,
) -> Result<(metamodelica::Ref<DAE::Exp>, metamodelica::Ref<AvlSetString::Tree>)> {
    let mut e: metamodelica::Ref<DAE::Exp> = e;
    let mut tree: metamodelica::Ref<AvlSetString::Tree> = tree;
    let mut f: ArcStr;
    let mut e1: metamodelica::Ref<DAE::Exp>;
    tree = (::match_deref::match_deref! { match &(&*e) {
        Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "OpenModelica_fmuLoadResource" }, expLst: Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Exp::SCONST { string: __esc_f }, tail: Deref @ metamodelica::ListNode::Nil }, .. } => {
            f = (*__esc_f).clone();
            AvlSetString::add(tree, metamodelica::AsArg::as_arg(&f))?
        },
        Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "OpenModelica_uriToFilename" }, expLst: Deref @ metamodelica::ListNode::Cons { head: __esc_e1, tail: _ }, .. } => {
            e1 = (*__esc_e1).clone();
            Error::addMessage(Error::FMI_URI_RESOLVE.clone(), list![ExpressionBasics::printExpStr(e1.clone())?])?;
            Mutable::update(unknownUri, true);
            tree
        },
        _ => tree,
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok((e, tree))
}

