fn aliasSimEq(
    mut eq: metamodelica::Ref<SimCode::SimEqSystem>,
    mut cache: (
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<SimCode::SimEqSystem>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<Option<(metamodelica::Ref<SimCode::SimEqSystem>, i32)>>,
        ),
        i32,
        (
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<SimCode::SimEqSystem>) -> Result<i32> + 'static>,
            Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<SimCode::SimEqSystem>,
                        metamodelica::Ref<SimCode::SimEqSystem>,
                    ) -> Result<bool>
                    + 'static,
            >,
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<SimCode::SimEqSystem>) -> Result<ArcStr> + 'static>,
            Arc<dyn ::std::ops::Fn(i32) -> Result<ArcStr> + 'static>,
        ),
    ),
) -> Result<(
    metamodelica::Ref<SimCode::SimEqSystem>,
    (
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<SimCode::SimEqSystem>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<Option<(metamodelica::Ref<SimCode::SimEqSystem>, i32)>>,
        ),
        i32,
        (
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<SimCode::SimEqSystem>) -> Result<i32> + 'static>,
            Arc<
                dyn ::std::ops::Fn(
                        metamodelica::Ref<SimCode::SimEqSystem>,
                        metamodelica::Ref<SimCode::SimEqSystem>,
                    ) -> Result<bool>
                    + 'static,
            >,
            Arc<dyn ::std::ops::Fn(metamodelica::Ref<SimCode::SimEqSystem>) -> Result<ArcStr> + 'static>,
            Arc<dyn ::std::ops::Fn(i32) -> Result<ArcStr> + 'static>,
        ),
    ),
)> {
    let mut eq: metamodelica::Ref<SimCode::SimEqSystem> = eq;
    let mut cache: (
        metamodelica::Array<metamodelica::List<(metamodelica::Ref<SimCode::SimEqSystem>, i32)>>,
        (
            i32,
            i32,
            metamodelica::Array<Option<(metamodelica::Ref<SimCode::SimEqSystem>, i32)>>,
        ),
        i32,
        (
            HashTableSimCodeEqCache::FuncHashCref,
            HashTableSimCodeEqCache::FuncCrefEqual,
            HashTableSimCodeEqCache::FuncCrefStr,
            HashTableSimCodeEqCache::FuncExpStr,
        ),
    ) = cache;
    let mut ix: i32;
    let mut aliasOf: i32;
    ix = SimCodeCodegenUtil::simEqSystemIndex(&eq)?;
    if BaseHashTable::hasKey(eq.clone(), &cache)? {
        aliasOf = BaseHashTable::get(eq.clone(), &cache)?;
        if aliasOf != ix {
            eq = metamodelica::Ref::new(SimCode::SimEqSystem::SES_ALIAS {
                index: ix,
                aliasOf: BaseHashTable::get(eq, &cache)?,
            });
        }
        return Ok((eq, cache));
    }
    if (::match_deref::match_deref! { match &(eq.clone()) {
        Deref @ SimCode::SimEqSystem::SES_SIMPLE_ASSIGN { .. } => true,
        Deref @ SimCode::SimEqSystem::SES_ARRAY_CALL_ASSIGN { .. } => true,
        Deref @ SimCode::SimEqSystem::SES_ALGORITHM { statements: Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Statement::STMT_NORETCALL { .. }, tail: Deref @ metamodelica::ListNode::Nil }, .. } => true,
        _ => false,
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } }) {
        cache = BaseHashTable::add((eq.clone(), ix), cache)?;
    }
    Ok((eq, cache))
}

pub fn generateRunnerBatScript(mut code: &metamodelica::Ref<SimCode::SimCode>) -> Result<ArcStr> {
    let mut fileName: ArcStr = arcstr::literal!("");
    let mut file: File::File = File::File(File::noReference())?;
    fileName = 'mc: {
        let __mc_input = &**code;
        if let Ok((__v, __wb0)) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                Deref @ SimCode::SimCode { .. } => {
                    let mut r#str: ArcStr;
                    let mut omdevPath: ArcStr;
                    let mut msysPath: ArcStr;
                    let mut mingwDir: ArcStr;
                    let mut installDir: ArcStr;
                    let mut isMSVC: bool;
                    let mut locations_lst: metamodelica::List<ArcStr>;
                    let mut fileName: ArcStr = fileName.clone();
                    fileName = { let mut __mm_s = String::new(); __mm_s.push_str(&*code.fileNamePrefix); __mm_s.push_str(&*literal!(".bat")); ArcStr::from(__mm_s) };
                    File::open(file.clone(), fileName.clone(), File::Mode::Write.clone());
                    (locations_lst, _) = getDirectoriesForDLLsFromLinkLibs(&code.makefileParams.libs)?;
                    installDir = Settings::getInstallationDirectoryPath()?;
                    locations_lst = metamodelica::cons({ let mut __mm_s = String::new(); __mm_s.push_str(&*installDir); __mm_s.push_str(&*literal!("/bin")); ArcStr::from(__mm_s) }, locations_lst.clone());
                    locations_lst = metamodelica::cons({ let mut __mm_s = String::new(); __mm_s.push_str(&*installDir); __mm_s.push_str(&*literal!("/lib/")); __mm_s.push_str(&*Config::targetTriple()?); __mm_s.push_str(&*literal!("/omc")); ArcStr::from(__mm_s) }, locations_lst.clone());
                    omdevPath = Util::makeValueOrDefault(&System::readEnv, literal!("OMDEV"), Settings::getInstallationDirectoryPath()?);
                    msysPath = { let mut __mm_s = String::new(); __mm_s.push_str(&*omdevPath); __mm_s.push_str(&*literal!("/tools/msys")); ArcStr::from(__mm_s) };
                    mingwDir = System::openModelicaPlatform();
                    isMSVC = 0 == System::stringFind(mingwDir.clone(), literal!("msvc"))?;
                    if !(isMSVC) {
                        locations_lst = metamodelica::cons({ let mut __mm_s = String::new(); __mm_s.push_str(&*msysPath); __mm_s.push_str(&*literal!("/")); __mm_s.push_str(&*mingwDir); __mm_s.push_str(&*literal!("/bin")); ArcStr::from(__mm_s) }, locations_lst.clone());
                        locations_lst = metamodelica::cons({ let mut __mm_s = String::new(); __mm_s.push_str(&*msysPath); __mm_s.push_str(&*literal!("/")); __mm_s.push_str(&*mingwDir); __mm_s.push_str(&*literal!("/lib/gcc/")); __mm_s.push_str(&*System::gccDumpMachine()); __mm_s.push_str(&*literal!("/")); __mm_s.push_str(&*System::gccVersion()); ArcStr::from(__mm_s) }, locations_lst.clone());
                        locations_lst = metamodelica::cons({ let mut __mm_s = String::new(); __mm_s.push_str(&*msysPath); __mm_s.push_str(&*literal!("/usr/bin")); ArcStr::from(__mm_s) }, locations_lst.clone());
                    }
                    locations_lst = locations_lst.clone().reverse();
                    r#str = { let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("@echo off\n")); __mm_s.push_str(&*literal!("setlocal\n")); __mm_s.push_str(&*literal!("SET PATH=")); __mm_s.push_str(&*stringDelimitList(locations_lst.clone(), literal!(";"))); __mm_s.push_str(&*literal!(";%PATH%\n")); __mm_s.push_str(&*literal!("SET ERRORLEVEL=\n")); __mm_s.push_str(&*literal!("CALL \"%CD%/")); __mm_s.push_str(&*code.fileNamePrefix); __mm_s.push_str(&*literal!(".exe\" %*\n")); __mm_s.push_str(&*literal!("SET RESULT=%ERRORLEVEL%\n")); __mm_s.push_str(&*literal!("endlocal\n")); __mm_s.push_str(&*literal!("EXIT /b %RESULT%\n")); ArcStr::from(__mm_s) };
                    File::write(file.clone(), r#str.clone());
                    Ok((fileName.clone(), fileName.clone()))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            fileName = __wb0;
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                _ => {
                    Error::addInternalError(literal!("SimCodeMain.generateRunnerBatScript failed"), metamodelica::sourceInfo!("SimCode/SimCodeUtil.mo"))?;
                    Ok(literal!(""))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        return Err("matchcontinue: no arm matched");
    };
    Ok(fileName)
}

pub fn getDirectoriesForDLLsFromLinkLibs(
    mut libsAndLinkDirs: &metamodelica::List<ArcStr>,
) -> Result<(metamodelica::List<ArcStr>, metamodelica::List<ArcStr>)> {
    let mut outLocations: metamodelica::List<ArcStr> = metamodelica::nil();
    let mut outLibs: metamodelica::List<ArcStr> = metamodelica::nil();
    for mut r#str in &**libsAndLinkDirs {
        if StringUtil::startsWith(r#str.clone(), literal!("\"-L")) {
            outLocations = listAppend(
                list![substring(r#str.clone(), 4, ((r#str).len() as i32) - 1)?],
                outLocations,
            );
        } else if StringUtil::startsWith(r#str.clone(), literal!("-l")) {
            outLibs = listAppend(list![substring(r#str.clone(), 3, ((r#str).len() as i32))?], outLibs);
        }
    }
    outLocations = outLocations.reverse();
    outLibs = outLibs.reverse();
    Ok((outLocations, outLibs))
}

pub(crate) fn getCmakeCrossPlatformSuffixes() -> ArcStr {
    let mut cmakeCode: ArcStr;
    cmakeCode = {
        let mut __mm_s = String::new();
        __mm_s.push_str(&*literal!("\n# Cross-Platform CMAKE_FIND_LIBRARY_SUFFIXES\n"));
        __mm_s.push_str(&*literal!("if(WIN32)\n"));
        __mm_s.push_str(&*literal!(
            "  set(CMAKE_FIND_LIBRARY_SUFFIXES \".lib\" \".dll\" \".a\")\n"
        ));
        __mm_s.push_str(&*literal!("elseif(APPLE)\n"));
        __mm_s.push_str(&*literal!("  set(CMAKE_FIND_LIBRARY_SUFFIXES \".dylib\" \".a\")\n"));
        __mm_s.push_str(&*literal!("else()\n"));
        __mm_s.push_str(&*literal!("  set(CMAKE_FIND_LIBRARY_SUFFIXES \".so\" \".a\")\n"));
        __mm_s.push_str(&*literal!("endif()\n"));
        ArcStr::from(__mm_s)
    };
    cmakeCode
}

pub fn getCmakeLinkLibrariesCode(mut libs: &metamodelica::List<ArcStr>) -> Result<(ArcStr, ArcStr)> {
    fn addDockerVol(mut istring: &ArcStr) -> ArcStr {
        let mut ostring: ArcStr = {
            let mut __mm_s = String::new();
            __mm_s.push_str(&*literal!("\"${DOCKER_VOL_DIR}"));
            __mm_s.push_str(&*istring);
            __mm_s.push_str(&*literal!("\""));
            ArcStr::from(__mm_s)
        };
        ostring
    }

    let mut needModelicaExternalC: ArcStr = literal!("OFF");
    let mut cmakeCode: ArcStr = literal!("");
    let mut locations: metamodelica::List<ArcStr>;
    let mut libraries: metamodelica::List<ArcStr>;
    (locations, libraries) = getDirectoriesForDLLsFromLinkLibs(libs)?;
    locations = listAppend(
        list![{
            let mut __mm_s = String::new();
            __mm_s.push_str(&*Settings::getInstallationDirectoryPath()?);
            __mm_s.push_str(&*literal!("/lib/${CMAKE_LIBRARY_ARCHITECTURE}/omc"));
            ArcStr::from(__mm_s)
        }],
        locations,
    );
    locations = listAppend(
        list![{
            let mut __mm_s = String::new();
            __mm_s.push_str(&*Settings::getInstallationDirectoryPath()?);
            __mm_s.push_str(&*literal!("/bin"));
            ArcStr::from(__mm_s)
        }],
        locations,
    );
    locations = List::map(locations, &move |__a0: ArcStr| -> metamodelica::Result<_> {
        ::std::result::Result::Ok(addDockerVol(&__a0))
    })?;
    cmakeCode = {
        let mut __mm_s = String::new();
        __mm_s.push_str(&*cmakeCode);
        __mm_s.push_str(&*literal!("set(EXTERNAL_LIBDIRECTORIES "));
        __mm_s.push_str(&*stringDelimitList(
            locations,
            literal!("\n                            "),
        ));
        __mm_s.push_str(&*literal!(")\n"));
        ArcStr::from(__mm_s)
    };
    cmakeCode = {
        let mut __mm_s = String::new();
        __mm_s.push_str(&*cmakeCode);
        __mm_s.push_str(&*literal!(
            "om_add_target_library_directories(EXTERNAL_LIBDIRECTORIES)\n"
        ));
        ArcStr::from(__mm_s)
    };
    cmakeCode = {
        let mut __mm_s = String::new();
        __mm_s.push_str(&*cmakeCode);
        __mm_s.push_str(&*getCmakeCrossPlatformSuffixes());
        __mm_s.push_str(&*literal!("\n"));
        ArcStr::from(__mm_s)
    };
    for mut lib in &*libraries {
        if List::contains(
            &(list![
                literal!("ModelicaStandardTables"),
                literal!("ModelicaIO"),
                literal!("ModelicaMatIO")
            ]),
            lib.clone(),
            &fnptr!(stringEqual, ArcStr, ArcStr),
        )? {
            needModelicaExternalC = literal!("ON");
        } else if metamodelica::stringEq(&lib, &(literal!("zlib"))) {
            cmakeCode = {
                let mut __mm_s = String::new();
                __mm_s.push_str(&*cmakeCode);
                __mm_s.push_str(&*literal!("find_library("));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!("             NAMES "));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!(
                    "             PATHS ${EXTERNAL_LIBDIRECTORIES} NO_DEFAULT_PATH NO_CMAKE_FIND_ROOT_PATH)\n"
                ));
                __mm_s.push_str(&*literal!("if(NOT "));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!(")\n"));
                __mm_s.push_str(&*literal!("  message(WARNING \"Could not find library zlib\")"));
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!("  message(STATUS \"zlib is referred by ModelicaMatIO, but not used by default. Try compiling without linking.\")"));
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!("else()\n"));
                __mm_s.push_str(&*literal!("  message(STATUS \"Linking ${"));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("}\")"));
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!("  target_link_libraries(${FMU_NAME_HASH} PRIVATE ${"));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("})"));
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!("  list(APPEND RUNTIME_DEPENDS ${"));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("})"));
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!("endif()\n"));
                ArcStr::from(__mm_s)
            };
        } else {
            cmakeCode = {
                let mut __mm_s = String::new();
                __mm_s.push_str(&*cmakeCode);
                __mm_s.push_str(&*literal!("find_library("));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!("             NAMES "));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("\n"));
                __mm_s.push_str(&*literal!(
                    "             PATHS ${EXTERNAL_LIBDIRECTORIES} NO_DEFAULT_PATH NO_CMAKE_FIND_ROOT_PATH)\n"
                ));
                __mm_s.push_str(&*literal!("if(NOT "));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!(")\n"));
                __mm_s.push_str(&*literal!("  message(FATAL_ERROR \"Could not find library "));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("\")\n"));
                __mm_s.push_str(&*literal!("endif()\n"));
                __mm_s.push_str(&*literal!("message(STATUS \"Linking ${"));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("}\")\n"));
                __mm_s.push_str(&*literal!("target_link_libraries(${FMU_NAME_HASH} PRIVATE ${"));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("})\n"));
                __mm_s.push_str(&*literal!("list(APPEND RUNTIME_DEPENDS ${"));
                __mm_s.push_str(&*lib);
                __mm_s.push_str(&*literal!("})\n"));
                ArcStr::from(__mm_s)
            };
        }
    }
    Ok((needModelicaExternalC, cmakeCode))
}

pub fn getCmakeSundialsLinkCode(
    mut fmiSimulationFlags: Option<SimCode::FmiSimulationFlags>,
) -> Result<(ArcStr, ArcStr)> {
    let mut needCvode: ArcStr = literal!("OFF");
    let mut cvodeDirectory: ArcStr = literal!("\"\"");
    if cvodeFmiFlagIsSet(fmiSimulationFlags)? {
        needCvode = literal!("ON");
        cvodeDirectory = {
            let mut __mm_s = String::new();
            __mm_s.push_str(&*literal!("\"${DOCKER_VOL_DIR}"));
            __mm_s.push_str(&*Settings::getInstallationDirectoryPath()?);
            __mm_s.push_str(&*literal!("/lib/${CMAKE_LIBRARY_ARCHITECTURE}/omc\""));
            ArcStr::from(__mm_s)
        };
    }
    Ok((needCvode, cvodeDirectory))
}

pub fn cvodeFmiFlagIsSet(mut fmiSimulationFlags: Option<SimCode::FmiSimulationFlags>) -> Result<bool> {
    let mut needsCvode: bool = false;
    let () = (match fmiSimulationFlags {
        Some(SimCode::FmiSimulationFlags::FMI_SIMULATION_FLAGS {
            nameValueTuples: mut nameValueTuples,
        }) => {
            let mut setting: ArcStr;
            let mut value: ArcStr;
            if !((nameValueTuples).is_empty()) {
                for mut tpl in &*nameValueTuples.clone() {
                    (setting, value) = tpl.clone();
                    if stringEqual(&setting, &(literal!("s"))) && stringEqual(&value, &(literal!("cvode"))) {
                        needsCvode = true;
                        break;
                    }
                }
            }
            ()
        }
        Some(SimCode::FmiSimulationFlags::FMI_SIMULATION_FLAGS_FILE { path: mut configFile }) => {
            let mut fileContent: ArcStr;
            fileContent = System::readFile(configFile.clone())?;
            if !(-1 == System::stringFind(fileContent, literal!("\"cvode\""))?) {
                needsCvode = true;
            }
            ()
        }
        _ => (),
    });
    Ok(needsCvode)
}

pub fn stripIncludeFlag(mut include: ArcStr) -> Result<ArcStr> {
    let mut directory: ArcStr = substring(include.clone(), 4, ((include).len() as i32) - 1)?;
    Ok(directory)
}

pub fn make2CMakeInclude(mut includes: &metamodelica::List<ArcStr>) -> Result<ArcStr> {
    let mut cmakeCode: ArcStr = literal!("");
    for mut include in &**includes {
        cmakeCode = {
            let mut __mm_s = String::new();
            __mm_s.push_str(&*cmakeCode);
            __mm_s.push_str(&*literal!("\n                                               "));
            __mm_s.push_str(&*literal!("\"${DOCKER_VOL_DIR}"));
            __mm_s.push_str(&*stripIncludeFlag(include.clone())?);
            __mm_s.push_str(&*literal!("\""));
            ArcStr::from(__mm_s)
        };
    }
    Ok(cmakeCode)
}

pub fn msvcEnvironment() -> Result<ArcStr> {
    let mut prefix: ArcStr = literal!("");
    if metamodelica::stringEq(&arcstr::literal!(Autoconf::os), &(literal!("Windows_NT")))
        && StringUtil::startsWith(Config::simulationCodeTarget()?, literal!("msvc"))
    {
        prefix = {
            let mut __mm_s = String::new();
            __mm_s.push_str(&*literal!("call \""));
            __mm_s.push_str(&*System::stringReplace(
                {
                    let mut __mm_s = String::new();
                    __mm_s.push_str(&*Settings::getInstallationDirectoryPath()?);
                    __mm_s.push_str(&*literal!("/share/omc/scripts/msvc_env.bat"));
                    ArcStr::from(__mm_s)
                },
                literal!("/"),
                literal!("\\"),
            )?);
            __mm_s.push_str(&*literal!("\" && "));
            ArcStr::from(__mm_s)
        };
    }
    Ok(prefix)
}

pub fn getCMakeVersion(mut pathToCMake: &ArcStr) -> Result<SemanticVersion::Version> {
    let mut cmakeVersion: SemanticVersion::Version;
    let mut retVal: i32;
    let mut cmakeVersionLogFile: ArcStr = literal!("systemCall_cmakeVersion.log");
    let mut regexOut: metamodelica::List<ArcStr>;
    let mut numMatches: i32;
    let mut cmakeVersionString: ArcStr;
    retVal = System::systemCallRestrictedEnv(
        {
            let mut __mm_s = String::new();
            __mm_s.push_str(&*msvcEnvironment()?);
            __mm_s.push_str(&*pathToCMake);
            __mm_s.push_str(&*literal!(" --version"));
            ArcStr::from(__mm_s)
        },
        cmakeVersionLogFile.clone(),
    )?;
    if 0 != retVal {
        Error::addInternalError(
            {
                let mut __mm_s = String::new();
                __mm_s.push_str(&*literal!("Failed to get version from "));
                __mm_s.push_str(&*pathToCMake);
                __mm_s.push_str(&*literal!(": "));
                __mm_s.push_str(&*System::readFile(cmakeVersionLogFile.clone())?);
                ArcStr::from(__mm_s)
            },
            metamodelica::sourceInfo!("SimCode/SimCodeUtil.mo"),
        )?;
        System::removeFile(cmakeVersionLogFile.clone());
        return Err("fail");
    }
    (numMatches, regexOut) = System::regex(
        System::trimWhitespace(System::readFile(cmakeVersionLogFile.clone())?),
        literal!("[0-9]+\\.[0-9]+\\.[0-9]+"),
        1,
        true,
        false,
    );
    if numMatches == 0 {
        System::removeFile(cmakeVersionLogFile.clone());
        Error::addInternalError(
            {
                let mut __mm_s = String::new();
                __mm_s.push_str(&*literal!("Failed to read semantic version from "));
                __mm_s.push_str(&*pathToCMake);
                ArcStr::from(__mm_s)
            },
            metamodelica::sourceInfo!("SimCode/SimCodeUtil.mo"),
        )?;
        return Err("fail");
    }
    cmakeVersionString = (regexOut).head().cloned()?;
    cmakeVersion = SemanticVersion::parse(cmakeVersionString, false)?;
    System::removeFile(cmakeVersionLogFile);
    Ok(cmakeVersion)
}
